        'date' => ['hu' => '2026. május 19.', 'en' => 'May 19, 2026', 'de' => '19. Mai 2026', 'ro' => '19 mai 2026', 'sk' => '19. mája 2026'],
        'items' => [
            ['hu' => '<strong>Multi-szervezet / multi-tenant támogatás:</strong> A NationForge Pro mostantól több független szervezetet (tenant) tud kezelni egyetlen telepítésen belül. Minden adat-szintű lekérdezéshez automatikusan hozzáadódik a szervezet-szűrő a <code>BelongsToOrganization</code> globális scope-on keresztül — így a különböző szervezetek adatai teljes mértékben szeparáltak maradnak egymástól.',
             'en'  => '<strong>Multi-organisation / multi-tenant support:</strong> NationForge Pro can now manage multiple independent organisations (tenants) within a single installation. An organisation filter is automatically applied to every data-level query via the <code>BelongsToOrganization</code> global scope — ensuring complete data isolation between organisations.',
             'de'  => '<strong>Multi-Organisation / Multi-Tenant-Unterstützung:</strong> NationForge Pro kann nun mehrere unabhängige Organisationen (Tenants) innerhalb einer einzigen Installation verwalten. Über den globalen Scope <code>BelongsToOrganization</code> wird jeder datenseitigen Abfrage automatisch ein Organisationsfilter hinzugefügt — dadurch bleiben die Daten verschiedener Organisationen vollständig voneinander getrennt.',
             'ro'  => '<strong>Suport multi-organizație / multi-tenant:</strong> NationForge Pro poate gestiona acum mai multe organizații independente (tenants) într-o singură instalare. Un filtru de organizație este adăugat automat la fiecare interogare la nivel de date prin scope-ul global <code>BelongsToOrganization</code> — asigurând izolarea completă a datelor între organizații.',
             'sk'  => '<strong>Podpora multi-organizácie / multi-tenant:</strong> NationForge Pro teraz môže spravovať viacero nezávislých organizácií (tenantov) v rámci jednej inštalácie. Filter organizácie sa automaticky pridáva ku každému dotazu na úrovni dát prostredníctvom globálneho scope <code>BelongsToOrganization</code> — čím sa zabezpečí úplná izolácia dát medzi organizáciami.'],
            ['hu' => '<strong>Szervezetek menüpont az oldalsávban (Pro, csak strict-admin):</strong> A bal oldali navigációs sávban megjelent az <em>Szervezetek</em> menüpont, amely csak a legmagasabb jogosultsági szintű (strict-admin) felhasználók számára látható. Az oldalon listázhatók, létrehozhatók, szerkeszthetők és törölhetők a szervezetek.',
             'en'  => '<strong>Organisations menu item in sidebar (Pro, strict-admin only):</strong> An <em>Organisations</em> menu item has been added to the left navigation sidebar, visible only to users with the highest permission level (strict-admin). The page allows listing, creating, editing and deleting organisations.',
             'de'  => '<strong>Organisationen-Menüpunkt in der Seitenleiste (Pro, nur strict-admin):</strong> Ein <em>Organisationen</em>-Menüpunkt wurde zur linken Navigationsseitenleiste hinzugefügt, der nur für Benutzer mit der höchsten Berechtigungsstufe (strict-admin) sichtbar ist. Die Seite ermöglicht das Auflisten, Erstellen, Bearbeiten und Löschen von Organisationen.',
             'ro'  => '<strong>Elementul de meniu Organizații în bara laterală (Pro, doar strict-admin):</strong> Un element de meniu <em>Organizații</em> a fost adăugat în bara de navigare laterală stângă, vizibil doar pentru utilizatorii cu cel mai înalt nivel de permisiuni (strict-admin). Pagina permite listarea, crearea, editarea și ștergerea organizațiilor.',
             'sk'  => '<strong>Položka menu Organizácie v bočnom paneli (Pro, len strict-admin):</strong> Položka menu <em>Organizácie</em> bola pridaná do ľavého navigačného bočného panela, viditeľná len pre používateľov s najvyššou úrovňou oprávnení (strict-admin). Stránka umožňuje zobrazenie, vytváranie, úpravu a odstraňovanie organizácií.'],
            ['hu' => '<strong>BelongsToOrganization trait javítás:</strong> A <code>qualifyColumn()</code> hívás helyett a helyes <code>$query->qualifyColumn()</code> metódus használata a globális scope-ban — statikus kontextusból való hívás által okozott hibát szüntet meg.',
             'en'  => '<strong>BelongsToOrganization trait fix:</strong> Replaced the static <code>qualifyColumn()</code> call with the correct <code>$query->qualifyColumn()</code> in the global scope — eliminates errors caused by calling from a static context.',
             'de'  => '<strong>BelongsToOrganization Trait-Korrektur:</strong> Ersetzte den statischen <code>qualifyColumn()</code>-Aufruf durch das korrekte <code>$query->qualifyColumn()</code> im globalen Scope — behebt Fehler, die durch den Aufruf aus einem statischen Kontext verursacht wurden.',
             'ro'  => '<strong>Remedierea trait-ului BelongsToOrganization:</strong> Apelul static <code>qualifyColumn()</code> a fost înlocuit cu corectul <code>$query->qualifyColumn()</code> în scope-ul global — elimină erorile cauzate de apelul din context static.',
             'sk'  => '<strong>Oprava traitu BelongsToOrganization:</strong> Statické volanie <code>qualifyColumn()</code> bolo nahradené správnym <code>$query->qualifyColumn()</code> v globálnom scope — odstraňuje chyby spôsobené volaním zo statického kontextu.'],
        ],
    ],

    [
        'version' => 'v1.26.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 18.', 'en' => 'May 18, 2026', 'de' => '18. Mai 2026', 'ro' => '18 mai 2026', 'sk' => '18. mája 2026'],
        'items' => [
            ['hu' => '<strong>Nyilvános changelog oldal (<code>/changelog</code>):</strong> A verziókövetés oldal mostantól bejelentkezés nélkül is elérhető a <code>/changelog</code> URL-en. Az oldal tartalmazza a NationForge logót, a Programozás Kft. Facebook-hivatkozást, HU / EN / DE / RO / SK nyelvváltó zászlókat és egy Bejelentkezés gombot. Az admin bejelentkezési oldalon megjelent egy közvetlen hivatkozás az oldalra.',
             'en'  => '<strong>Public changelog page (<code>/changelog</code>):</strong> The changelog is now publicly accessible at <code>/changelog</code> without login. The page includes the NationForge logo, a Programozás Kft. Facebook link, HU / EN / DE / RO / SK language switcher flags and a Login button. A direct link to the page was added to the admin login page.',
             'de'  => '<strong>Öffentliche Changelog-Seite (<code>/changelog</code>):</strong> Das Changelog ist jetzt ohne Anmeldung unter <code>/changelog</code> öffentlich zugänglich. Die Seite enthält das NationForge-Logo, einen Programozás Kft. Facebook-Link, HU / EN / DE / RO / SK Sprachumschalter-Flags und einen Anmelde-Button. Ein direkter Link zur Seite wurde auf der Admin-Anmeldeseite hinzugefügt.',
             'ro'  => '<strong>Pagină publică changelog (<code>/changelog</code>):</strong> Jurnalul de modificări este acum accesibil public la <code>/changelog</code> fără autentificare. Pagina include logo-ul NationForge, un link Facebook Programozás Kft., indicatoare de limbă HU / EN / DE / RO / SK și un buton de autentificare. Un link direct către pagină a fost adăugat pe pagina de autentificare admin.',
             'sk'  => '<strong>Verejná stránka changelog (<code>/changelog</code>):</strong> Záznam zmien je teraz verejne prístupný na <code>/changelog</code> bez prihlásenia. Stránka obsahuje logo NationForge, odkaz na Facebook Programozás Kft., prepínače jazykov HU / EN / DE / RO / SK a tlačidlo Prihlásenia. Priamy odkaz na stránku bol pridaný na stránku prihlásenia správcu.'],
            ['hu' => '<strong>Öt nyelvű changelog (HU / EN / DE / RO / SK):</strong> A verziókövetés oldal összes bejegyzése — verziószámok, dátumok, badge-ek és fejlesztési leírások — mind az öt támogatott nyelven jelenik meg a kiválasztott zászló alapján. A DE / RO / SK zászlókra kattintva az angolra esik vissza, ahol nincs külön fordítás.',
             'en'  => '<strong>Five-language changelog (HU / EN / DE / RO / SK):</strong> All entries on the changelog page — version numbers, dates, badges and descriptions — are displayed in all five supported languages based on the selected flag. DE / RO / SK flags fall back to English where no dedicated translation is available.',
             'de'  => '<strong>Fünfsprachiges Changelog (HU / EN / DE / RO / SK):</strong> Alle Einträge auf der Changelog-Seite — Versionsnummern, Daten, Badges und Beschreibungen — werden in allen fünf unterstützten Sprachen basierend auf der ausgewählten Flagge angezeigt. DE / RO / SK-Flags fallen auf Englisch zurück, wenn keine dedizierte Übersetzung verfügbar ist.',
             'ro'  => '<strong>Changelog în cinci limbi (HU / EN / DE / RO / SK):</strong> Toate intrările de pe pagina de changelog — numere de versiune, date, insigne și descrieri — sunt afișate în toate cele cinci limbi suportate pe baza steagului selectat. Steagurile DE / RO / SK revin la engleză unde nu există traducere dedicată.',
             'sk'  => '<strong>Päťjazyčný changelog (HU / EN / DE / RO / SK):</strong> Všetky záznamy na stránke changelog — čísla verzií, dátumy, odznaky a popisy — sú zobrazené vo všetkých piatich podporovaných jazykoch na základe vybranej vlajky. Vlajky DE / RO / SK sa vracajú k angličtine, kde nie je k dispozícii dedikovaný preklad.'],
            ['hu' => '<strong>Audit napló dátum formázás javítása:</strong> Az <code>AuditLog</code> modell <code>$timestamps = false</code> beállítása miatt a <code>created_at</code> mező néha szövegként érkezett, ami <code>format() on string</code> hibát okozott. Javítás: <code>\Carbon\Carbon::parse($log->created_at)->format(\'Y.m.d H:i\')</code> a nézetben.',
             'en'  => '<strong>Audit log date formatting fix:</strong> The <code>AuditLog</code> model\'s <code>$timestamps = false</code> setting caused the <code>created_at</code> field to sometimes arrive as a string, triggering a <code>format() on string</code> error. Fix: <code>\Carbon\Carbon::parse($log->created_at)->format(\'Y.m.d H:i\')</code> in the view.',
             'de'  => '<strong>Fehlerbehebung bei der Datumsformatierung im Audit-Log:</strong> Die Einstellung <code>$timestamps = false</code> im <code>AuditLog</code>-Modell verursachte, dass das Feld <code>created_at</code> manchmal als String ankam und einen <code>format() on string</code>-Fehler auslöste. Behebung: <code>\Carbon\Carbon::parse($log->created_at)->format(\'Y.m.d H:i\')</code> in der Ansicht.',
             'ro'  => '<strong>Remedierea formatării datei în jurnalul de audit:</strong> Setarea <code>$timestamps = false</code> a modelului <code>AuditLog</code> a cauzat ca câmpul <code>created_at</code> să ajungă uneori ca șir de caractere, declanșând o eroare <code>format() on string</code>. Remediere: <code>\Carbon\Carbon::parse($log->created_at)->format(\'Y.m.d H:i\')</code> în vizualizare.',
             'sk'  => '<strong>Oprava formátovania dátumu v audit logu:</strong> Nastavenie <code>$timestamps = false</code> v modeli <code>AuditLog</code> spôsobilo, že pole <code>created_at</code> niekedy prišlo ako reťazec, čo vyvolalo chybu <code>format() on string</code>. Oprava: <code>\Carbon\Carbon::parse($log->created_at)->format(\'Y.m.d H:i\')</code> v pohľade.'],
        ],
    ],

    [
        'version' => 'v1.26.0 Pro',
        'badge'   => [
            'text'  => ['hu' => 'Pro', 'en' => 'Pro', 'de' => 'Pro', 'ro' => 'Pro', 'sk' => 'Pro'],
            'style' => 'background:rgba(247,184,75,0.18);color:#946800;border:1px solid rgba(247,184,75,0.4);',
        ],
        'date' => ['hu' => '2026. május 18.', 'en' => 'May 18, 2026', 'de' => '18. Mai 2026', 'ro' => '18 mai 2026', 'sk' => '18. mája 2026'],
        'items' => [
            ['hu' => '<strong>NationForge Pro repository elindítva:</strong> A <code>nationforge-pro</code> privát GitHub repó szinkronizálva a Community összes fejlesztésével (99 commit behúzva). A Pro verzió tartalmaz mindent ami a Community-ban van, kiegészítve a Pro-exkluzív funkciókkal.',
             'en'  => '<strong>NationForge Pro repository launched:</strong> The <code>nationforge-pro</code> private GitHub repo was synchronised with all Community developments (99 commits merged in). The Pro version contains everything in Community, extended with Pro-exclusive features.',
             'de'  => '<strong>NationForge Pro-Repository gestartet:</strong> Das private GitHub-Repo <code>nationforge-pro</code> wurde mit allen Community-Entwicklungen synchronisiert (99 Commits zusammengeführt). Die Pro-Version enthält alles aus der Community, erweitert um Pro-exklusive Funktionen.',
             'ro'  => '<strong>Repository NationForge Pro lansat:</strong> Repo-ul privat GitHub <code>nationforge-pro</code> a fost sincronizat cu toate dezvoltările Community (99 de commit-uri îmbinate). Versiunea Pro conține tot ce există în Community, extins cu funcții exclusive Pro.',
             'sk'  => '<strong>Repozitár NationForge Pro spustený:</strong> Súkromný GitHub repozitár <code>nationforge-pro</code> bol synchronizovaný so všetkými vývojmi Community (zlúčených 99 commitov). Verzia Pro obsahuje všetko z Community, rozšírená o funkcie exkluzívne pre Pro.'],
            ['hu' => '<strong>Helyi Pro fejlesztői környezet (<code>nationforge-pro.test</code>):</strong> Az XAMPP Apache konfigurációban beállításra került egy dedikált VirtualHost, amely a <code>nationforge-pro.test</code> doménen, a Community-tól teljesen függetlenül szolgálja ki a Pro verziót. A <code>.env</code>, <code>composer install</code>, <code>npm run build</code> és az <code>ASSET_URL</code> konfiguráció teljes körűen elvégezve.',
             'en'  => '<strong>Local Pro development environment (<code>nationforge-pro.test</code>):</strong> A dedicated VirtualHost was configured in the XAMPP Apache setup, serving the Pro version on the <code>nationforge-pro.test</code> domain, fully independent from the Community. The <code>.env</code>, <code>composer install</code>, <code>npm run build</code> and <code>ASSET_URL</code> configuration were completed in full.',
             'de'  => '<strong>Lokale Pro-Entwicklungsumgebung (<code>nationforge-pro.test</code>):</strong> Ein dedizierter VirtualHost wurde in der XAMPP-Apache-Konfiguration eingerichtet, der die Pro-Version auf der Domain <code>nationforge-pro.test</code> völlig unabhängig von der Community bereitstellt. Die Konfiguration von <code>.env</code>, <code>composer install</code>, <code>npm run build</code> und <code>ASSET_URL</code> wurde vollständig durchgeführt.',
             'ro'  => '<strong>Mediu local de dezvoltare Pro (<code>nationforge-pro.test</code>):</strong> Un VirtualHost dedicat a fost configurat în setarea Apache XAMPP, servind versiunea Pro pe domeniul <code>nationforge-pro.test</code>, complet independent față de Community. Configurația <code>.env</code>, <code>composer install</code>, <code>npm run build</code> și <code>ASSET_URL</code> a fost finalizată complet.',
             'sk'  => '<strong>Lokálne vývojové prostredie Pro (<code>nationforge-pro.test</code>):</strong> Dedikovaný VirtualHost bol nakonfigurovaný v nastavení Apache XAMPP, ktorý obsluhuje verziu Pro na doméne <code>nationforge-pro.test</code>, úplne nezávisle od Community. Konfigurácia <code>.env</code>, <code>composer install</code>, <code>npm run build</code> a <code>ASSET_URL</code> bola úplne dokončená.'],
            ['hu' => '<strong><code>sync-from-community.bat</code> — egyetlen kattintásos szinkronizálás:</strong> A Pro könyvtárban elhelyezett szkript automatikusan végrehajtja a <code>git fetch community</code> + <code>git merge community/main</code> + <code>git push origin main</code> lépéseket. Merge konfliktus esetén leáll és útmutatót jelenít meg a manuális feloldáshoz.',
             'en'  => '<strong><code>sync-from-community.bat</code> — one-click sync:</strong> A script placed in the Pro directory automatically executes <code>git fetch community</code> + <code>git merge community/main</code> + <code>git push origin main</code>. In case of a merge conflict it stops and displays instructions for manual resolution.',
             'de'  => '<strong><code>sync-from-community.bat</code> — Synchronisierung mit einem Klick:</strong> Ein Skript im Pro-Verzeichnis führt automatisch <code>git fetch community</code> + <code>git merge community/main</code> + <code>git push origin main</code> aus. Bei einem Merge-Konflikt stoppt es und zeigt Anweisungen zur manuellen Lösung an.',
             'ro'  => '<strong><code>sync-from-community.bat</code> — sincronizare cu un singur clic:</strong> Un script plasat în directorul Pro execută automat <code>git fetch community</code> + <code>git merge community/main</code> + <code>git push origin main</code>. În caz de conflict de îmbinare, se oprește și afișează instrucțiuni pentru rezolvarea manuală.',
             'sk'  => '<strong><code>sync-from-community.bat</code> — synchronizácia jedným kliknutím:</strong> Skript umiestnený v adresári Pro automaticky vykoná <code>git fetch community</code> + <code>git merge community/main</code> + <code>git push origin main</code>. V prípade konfliktu zlúčenia sa zastaví a zobrazí pokyny na manuálne riešenie.'],
        ],
    ],

    [
        'version' => 'v1.25.0',
        'badge'   => [
            'text'  => ['hu' => 'Aktuális, Legújabb', 'en' => 'Current, Latest', 'de' => 'Aktuell, Neueste', 'ro' => 'Curent, Cel mai nou', 'sk' => 'Aktuálne, Najnovšie'],
            'style' => 'background:rgba(10,179,156,0.1);color:#0ab39c;',
        ],
        'date' => ['hu' => '2026. május 17.', 'en' => 'May 17, 2026', 'de' => '17. Mai 2026', 'ro' => '17 mai 2026', 'sk' => '17. mája 2026'],
        'items' => [
            ['hu' => '<strong>Google Calendar / iCal szinkronizáció:</strong> Nyilvános iCal feed (<code>/events.ics</code>) — az összes publikált esemény előfizethetővé vált bármilyen naptáralkalmazásban (Google Calendar, Apple Calendar, Outlook). Az Integrációk oldalon megjelenő URL egyetlen kattintással a Google Naptárba is hozzáadható.',
             'en'  => '<strong>Google Calendar / iCal sync:</strong> Public iCal feed (<code>/events.ics</code>) — all published events are now subscribable in any calendar app (Google Calendar, Apple Calendar, Outlook). The URL shown on the Integrations page can be added to Google Calendar in a single click.', 'de' => '<strong>Google Calendar / iCal-Synchronisation:</strong> Öffentlicher iCal-Feed (<code>/events.ics</code>) — alle veröffentlichten Ereignisse können nun in jeder Kalender-App abonniert werden (Google Calendar, Apple Calendar, Outlook). Die auf der Integrationsseite angezeigte URL kann mit einem Klick zu Google Calendar hinzugefügt werden.', 'ro' => '<strong>Sincronizare Google Calendar / iCal:</strong> Feed iCal public (<code>/events.ics</code>) — toate evenimentele publicate pot fi acum abonate în orice aplicație de calendar (Google Calendar, Apple Calendar, Outlook). URL-ul afișat pe pagina Integrări poate fi adăugat la Google Calendar cu un singur clic.', 'sk' => '<strong>Synchronizácia Google Calendar / iCal:</strong> Verejný iCal feed (<code>/events.ics</code>) — všetky zverejnené udalosti je teraz možné odoberať v ľubovoľnej kalendárovej aplikácii (Google Calendar, Apple Calendar, Outlook). URL zobrazená na stránke Integrácie sa dá pridať do Google Kalendára jediným kliknutím.'],
            ['hu' => '<strong>Facebook Esemény közzétevő:</strong> A publikált esemény nézetében megjelent egy <em>Közzétesz Facebookon</em> gomb, amely a Graph API v19.0 segítségével létrehozza az eseményt a beállított Facebook Oldalon. Az Integrációk oldalon adható meg az Oldal ID és a Page Access Token.',
             'en'  => '<strong>Facebook Event publisher:</strong> A <em>Publish to Facebook</em> button appears on published event pages, creating the event on the configured Facebook Page via Graph API v19.0. The Page ID and Page Access Token are configured on the Integrations page.', 'de' => '<strong>Facebook-Ereignis-Veröffentlicher:</strong> Ein <em>Auf Facebook veröffentlichen</em>-Button erscheint auf veröffentlichten Ereignisseiten und erstellt das Ereignis auf der konfigurierten Facebook-Seite über die Graph API v19.0. Die Seiten-ID und der Seiten-Zugriffstoken werden auf der Integrationsseite konfiguriert.', 'ro' => '<strong>Publisher de evenimente Facebook:</strong> Un buton <em>Publică pe Facebook</em> apare pe paginile de evenimente publicate, creând evenimentul pe Pagina Facebook configurată prin Graph API v19.0. ID-ul paginii și Token-ul de acces al paginii sunt configurate pe pagina Integrări.', 'sk' => '<strong>Publikátor udalostí na Facebooku:</strong> Tlačidlo <em>Zverejniť na Facebooku</em> sa zobrazuje na stránkach zverejnených udalostí a vytvára udalosť na nakonfigurovanej stránke Facebook prostredníctvom Graph API v19.0. ID stránky a prístupový token stránky sa konfigurujú na stránke Integrácie.'],
            ['hu' => '<strong>Zapier & Make (Integromat) integráció:</strong> A meglévő kimenő webhook rendszer (v1.24.0) az alapja. Az új Integrációk oldalon lépésről lépésre útmutató mutatja, hogyan kell Zapier Catch Hook és Make Custom Webhook triggert összekapcsolni a NationForge-zal — kód nélkül.',
             'en'  => '<strong>Zapier & Make (Integromat) integration:</strong> Built on the existing outgoing webhook system (v1.24.0). The new Integrations page provides a step-by-step guide on how to connect Zapier Catch Hook and Make Custom Webhook triggers to NationForge — no code required.', 'de' => '<strong>Zapier & Make (Integromat) Integration:</strong> Basiert auf dem bestehenden ausgehenden Webhook-System (v1.24.0). Die neue Integrationsseite bietet eine Schritt-für-Schritt-Anleitung zur Verbindung von Zapier Catch Hook und Make Custom Webhook-Triggern mit NationForge — kein Code erforderlich.', 'ro' => '<strong>Integrare Zapier & Make (Integromat):</strong> Construit pe sistemul de webhook-uri de ieșire existent (v1.24.0). Noua pagină Integrări oferă un ghid pas cu pas despre cum să conectați Zapier Catch Hook și declanșatoarele Make Custom Webhook la NationForge — nu este necesar cod.', 'sk' => '<strong>Integrácia Zapier & Make (Integromat):</strong> Postavená na existujúcom systéme odchádzajúcich webhookov (v1.24.0). Nová stránka Integrácie poskytuje podrobného sprievodcu, ako prepojiť Zapier Catch Hook a Make Custom Webhook spúšťače s NationForge — nevyžaduje sa žiadny kód.'],
            ['hu' => '<strong>Integrációk menüpont a sidebarban:</strong> Az összes külső integráció egy dedikált <em>Integrációk</em> oldalon érhető el — Google Calendar URL másoló, Facebook token beállítás és a Zapier/Make útmutató egy helyen.',
             'en'  => '<strong>Integrations menu item in sidebar:</strong> All external integrations are accessible from a dedicated <em>Integrations</em> page — Google Calendar URL copy, Facebook token configuration, and the Zapier/Make guide all in one place.', 'de' => '<strong>Integrationen-Menüpunkt in der Seitenleiste:</strong> Alle externen Integrationen sind über eine dedizierte <em>Integrationen</em>-Seite zugänglich — Google Calendar URL-Kopie, Facebook-Token-Konfiguration und die Zapier/Make-Anleitung an einem Ort.', 'ro' => '<strong>Element de meniu Integrări în bara laterală:</strong> Toate integrările externe sunt accesibile de pe o pagină dedicată <em>Integrări</em> — copierea URL-ului Google Calendar, configurarea token-ului Facebook și ghidul Zapier/Make, toate într-un singur loc.', 'sk' => '<strong>Položka menu Integrácie v bočnom paneli:</strong> Všetky externé integrácie sú dostupné z dedikovanej stránky <em>Integrácie</em> — kopírovanie URL Google Kalendára, konfigurácia tokenu Facebooku a sprievodca Zapier/Make na jednom mieste.'],
        ],
    ],

    [
        'version' => 'v1.24.0',
        'badge'   => [
            'text'  => ['hu' => 'Új modul', 'en' => 'New module', 'de' => 'Neues Modul', 'ro' => 'Modul nou', 'sk' => 'Nový modul'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 17.', 'en' => 'May 17, 2026', 'de' => '17. Mai 2026', 'ro' => '17 mai 2026', 'sk' => '17. mája 2026'],
        'items' => [
            ['hu' => '<strong>Kimenő webhookok:</strong> Konfigurálható HTTP POST küldés tetszőleges URL-re rendszereseményekre. 12 eseménytípus: <code>contact.*</code>, <code>event.*</code>, <code>donation.created</code>, <code>campaign.sent</code>, <code>task.*</code>, <code>drip.enrolled</code>. HMAC-SHA256 aláírás (<code>X-NationForge-Signature</code>). Kézbesítési napló per-kísérlet státusszal, HTTP kóddal és válasz törzzsel. Automatikus újrakísérlet (3 alkalom, 60 másodperces visszatartással) queue-n. Sikertelen kézbesítések manuális újraküldése az admin felületről.',
             'en'  => '<strong>Outgoing webhooks:</strong> Configurable HTTP POST to any URL on system events. 12 event types: <code>contact.*</code>, <code>event.*</code>, <code>donation.created</code>, <code>campaign.sent</code>, <code>task.*</code>, <code>drip.enrolled</code>. HMAC-SHA256 signing (<code>X-NationForge-Signature</code>). Delivery log with per-attempt status, HTTP code and response body. Automatic retry (3 attempts, 60 s backoff) via queue. Manual retry for failed deliveries from the admin UI.', 'de' => '<strong>Ausgehende Webhooks:</strong> Konfigurierbares HTTP POST an eine beliebige URL bei Systemereignissen. 12 Ereignistypen: <code>contact.*</code>, <code>event.*</code>, <code>donation.created</code>, <code>campaign.sent</code>, <code>task.*</code>, <code>drip.enrolled</code>. HMAC-SHA256-Signierung (<code>X-NationForge-Signature</code>). Zustellungsprotokoll mit Status pro Versuch, HTTP-Code und Antworttext. Automatischer Wiederholungsversuch (3 Versuche, 60 s Backoff) über Queue. Manueller Wiederholungsversuch für fehlgeschlagene Zustellungen aus der Admin-Oberfläche.', 'ro' => '<strong>Webhook-uri de ieșire:</strong> HTTP POST configurabil la orice URL la evenimentele sistemului. 12 tipuri de evenimente: <code>contact.*</code>, <code>event.*</code>, <code>donation.created</code>, <code>campaign.sent</code>, <code>task.*</code>, <code>drip.enrolled</code>. Semnare HMAC-SHA256 (<code>X-NationForge-Signature</code>). Jurnal de livrare cu starea per-tentativă, codul HTTP și corpul răspunsului. Reîncercare automată (3 tentative, 60 s backoff) prin coadă. Reîncercare manuală pentru livrările eșuate din interfața de administrare.', 'sk' => '<strong>Odchádzajúce webhooky:</strong> Konfigurovateľný HTTP POST na ľubovoľnú URL pri systémových udalostiach. 12 typov udalostí: <code>contact.*</code>, <code>event.*</code>, <code>donation.created</code>, <code>campaign.sent</code>, <code>task.*</code>, <code>drip.enrolled</code>. Podpisovanie HMAC-SHA256 (<code>X-NationForge-Signature</code>). Protokol doručenia so stavom za pokus, HTTP kódom a telom odpovede. Automatické opakovanie (3 pokusy, 60 s backoff) cez frontu. Manuálne opakovanie pre neúspešné doručenia z administrátorského rozhrania.'],
        ],
    ],

    [
        'version' => 'v1.23.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 17.', 'en' => 'May 17, 2026', 'de' => '17. Mai 2026', 'ro' => '17 mai 2026', 'sk' => '17. mája 2026'],
        'items' => [
            ['hu' => '<strong>Többnyelvű súgó (DE / RO / SK):</strong> A súgódokumentáció immár öt nyelven érhető el: magyar, angol, <em>német, román és szlovák</em>. Mind a 16 súgócikk teljes szövege le van fordítva. A nyelvváltó a súgó oldalsávjában érhető el — a kiválasztott nyelv azonnal érvényes.',
             'en'  => '<strong>Multilingual help (DE / RO / SK):</strong> The help documentation is now available in five languages: Hungarian, English, <em>German, Romanian and Slovak</em>. All 16 help articles are fully translated. The language switcher is available in the help sidebar — the selected language takes effect immediately.', 'de' => '<strong>Mehrsprachige Hilfe (DE / RO / SK):</strong> Die Hilfedokumentation ist jetzt in fünf Sprachen verfügbar: Ungarisch, Englisch, <em>Deutsch, Rumänisch und Slowakisch</em>. Alle 16 Hilfeartikel sind vollständig übersetzt. Der Sprachumschalter ist in der Hilfe-Seitenleiste verfügbar — die ausgewählte Sprache wirkt sofort.', 'ro' => '<strong>Ajutor multilingv (DE / RO / SK):</strong> Documentația de ajutor este acum disponibilă în cinci limbi: maghiară, engleză, <em>germană, română și slovacă</em>. Toate cele 16 articole de ajutor sunt complet traduse. Selectorul de limbă este disponibil în bara laterală a ajutorului — limba selectată intră în vigoare imediat.', 'sk' => '<strong>Viacjazyčná pomoc (DE / RO / SK):</strong> Dokumentácia pomocníka je teraz dostupná v piatich jazykoch: maďarčina, angličtina, <em>nemčina, rumunčina a slovenčina</em>. Všetkých 16 článkov pomocníka je plne preložených. Prepínač jazykov je dostupný v bočnom paneli pomocníka — vybraný jazyk sa uplatní okamžite.'],
            ['hu' => '<strong>Adatbázis-séma bővítése:</strong> A <code>help_articles</code> táblához hat új nullable szöveges oszlop adódott: <code>title_de</code>, <code>content_de</code>, <code>title_ro</code>, <code>content_ro</code>, <code>title_sk</code>, <code>content_sk</code>.',
             'en'  => '<strong>Database schema extension:</strong> Six new nullable text columns were added to the <code>help_articles</code> table: <code>title_de</code>, <code>content_de</code>, <code>title_ro</code>, <code>content_ro</code>, <code>title_sk</code>, <code>content_sk</code>.', 'de' => '<strong>Datenbankschema-Erweiterung:</strong> Sechs neue nullable Textspalten wurden zur Tabelle <code>help_articles</code> hinzugefügt: <code>title_de</code>, <code>content_de</code>, <code>title_ro</code>, <code>content_ro</code>, <code>title_sk</code>, <code>content_sk</code>.', 'ro' => '<strong>Extinderea schemei bazei de date:</strong> Șase noi coloane de text nullable au fost adăugate la tabelul <code>help_articles</code>: <code>title_de</code>, <code>content_de</code>, <code>title_ro</code>, <code>content_ro</code>, <code>title_sk</code>, <code>content_sk</code>.', 'sk' => '<strong>Rozšírenie schémy databázy:</strong> Do tabuľky <code>help_articles</code> bolo pridaných šesť nových stĺpcov nullable textu: <code>title_de</code>, <code>content_de</code>, <code>title_ro</code>, <code>content_ro</code>, <code>title_sk</code>, <code>content_sk</code>.'],
            ['hu' => '<strong>Súgószerkesztő — DE / RO / SK fülek:</strong> Az admin súgókezelő szerkesztő modáljában megjelent a Deutsch, Română és Slovenčina fül, így az összes nyelvi tartalom egy helyen szerkeszthető.',
             'en'  => '<strong>Help editor — DE / RO / SK tabs:</strong> The admin help editor modal now includes Deutsch, Română and Slovenčina tabs, allowing all language content to be edited from one place.', 'de' => '<strong>Hilfe-Editor — DE / RO / SK Tabs:</strong> Das Admin-Hilfe-Editor-Modal enthält jetzt Tabs für Deutsch, Română und Slovenčina, sodass alle Sprachinhalte von einem Ort aus bearbeitet werden können.', 'ro' => '<strong>Editor ajutor — file DE / RO / SK:</strong> Modalul de editare al ajutorului de administrare include acum file pentru Deutsch, Română și Slovenčina, permițând editarea conținutului în toate limbile dintr-un singur loc.', 'sk' => '<strong>Editor pomocníka — karty DE / RO / SK:</strong> Modálne okno editora pomocníka v administrácii teraz obsahuje karty Deutsch, Română a Slovenčina, čo umožňuje upravovať obsah vo všetkých jazykoch z jedného miesta.'],
            ['hu' => '<strong>Képek szinkronizálása minden nyelvre:</strong> A <code>HelpSyncImagesAllLangsSeeder</code> minden olyan cikknél, amelynek magyar tartalma képernyőképpel kezdődik, automatikusan előrészíti ugyanazt a képet a DE / RO / SK tartalomba is — duplikáció nélkül.',
             'en'  => '<strong>Image sync across all languages:</strong> The <code>HelpSyncImagesAllLangsSeeder</code> automatically prepends the same screenshot to DE / RO / SK content for every article whose Hungarian content starts with a screenshot image — without duplication.', 'de' => '<strong>Bildsynchronisation für alle Sprachen:</strong> Der <code>HelpSyncImagesAllLangsSeeder</code> fügt automatisch denselben Screenshot dem DE / RO / SK-Inhalt für jeden Artikel voran, dessen ungarischer Inhalt mit einem Screenshot-Bild beginnt — ohne Duplizierung.', 'ro' => '<strong>Sincronizarea imaginilor pentru toate limbile:</strong> <code>HelpSyncImagesAllLangsSeeder</code> adaugă automat același screenshot la conținutul DE / RO / SK pentru fiecare articol al cărui conținut maghiar începe cu o imagine screenshot — fără duplicare.', 'sk' => '<strong>Synchronizácia obrázkov pre všetky jazyky:</strong> <code>HelpSyncImagesAllLangsSeeder</code> automaticky pridáva rovnaký screenshot pred obsah DE / RO / SK pre každý článok, ktorého maďarský obsah začína obrázkom screenshotu — bez duplicity.'],
        ],
    ],

    [
        'version' => 'v1.22.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 16.', 'en' => 'May 16, 2026', 'de' => '16. Mai 2026', 'ro' => '16 mai 2026', 'sk' => '16. mája 2026'],
        'items' => [
            ['hu' => '<strong>Email megnyitás nyomon követése (tracking pixel):</strong> Minden elküldött kampánylevélbe és drip-levélbe egy láthatatlan 1×1 pixeles GIF-kép kerül. Ha a fogadó megnyitja az emailt, a kép lekérése rögzíti a megnyitás tényét. Az <code>email_sends</code> és <code>drip_sends</code> táblákhoz <code>opened_at</code> (nullable timestamp) mező adódott; a kampány összesítő <code>opened_count</code> számlálója automatikusan növekszik.',
             'en'  => '<strong>Email open tracking (pixel):</strong> Every sent campaign email and drip email now contains an invisible 1×1 GIF image. When the recipient opens the email, the image request records the open event. An <code>opened_at</code> (nullable timestamp) column was added to <code>email_sends</code> and <code>drip_sends</code>; the campaign summary <code>opened_count</code> counter increments automatically.', 'de' => '<strong>E-Mail-Öffnungs-Tracking (Pixel):</strong> Jede gesendete Kampagnen-E-Mail und Drip-E-Mail enthält nun ein unsichtbares 1×1 GIF-Bild. Wenn der Empfänger die E-Mail öffnet, zeichnet die Bildanfrage das Öffnungsereignis auf. Eine <code>opened_at</code>-Spalte (nullable Timestamp) wurde zu <code>email_sends</code> und <code>drip_sends</code> hinzugefügt; der Kampagnenzusammenfassungs-Zähler <code>opened_count</code> wird automatisch erhöht.', 'ro' => '<strong>Urmărirea deschiderilor de e-mail (pixel):</strong> Fiecare e-mail de campanie și e-mail drip trimis conține acum o imagine GIF invizibilă de 1×1. Când destinatarul deschide e-mailul, cererea de imagine înregistrează evenimentul de deschidere. O coloană <code>opened_at</code> (timestamp nullable) a fost adăugată la <code>email_sends</code> și <code>drip_sends</code>; contorul de rezumat al campaniei <code>opened_count</code> se incrementează automat.', 'sk' => '<strong>Sledovanie otvorení e-mailov (pixel):</strong> Každý odoslaný e-mail kampane a drip e-mail teraz obsahuje neviditeľný obrázok GIF 1×1. Keď príjemca otvorí e-mail, požiadavka na obrázok zaznamená udalosť otvorenia. Stĺpec <code>opened_at</code> (nullable timestamp) bol pridaný do <code>email_sends</code> a <code>drip_sends</code>; počítadlo súhrnu kampane <code>opened_count</code> sa automaticky zvyšuje.'],
            ['hu' => '<strong>Link-kattintás nyomon követése:</strong> Az emailben lévő összes külső link egy átirányító proxy URL-en keresztül kerül kiszolgálásra (<code>/track/click/{token}?to=...</code>). Kattintáskor a rendszer rögzíti a <code>clicked_at</code> időpontot és növeli a kampány <code>clicked_count</code> számlálóját, majd átirányít az eredeti célra. Az unsubscribe és nyomkövetési linkek kizárva az átírásból.',
             'en'  => '<strong>Link click tracking:</strong> All external links in emails are served through a redirect proxy URL (<code>/track/click/{token}?to=...</code>). On click, the system records the <code>clicked_at</code> timestamp and increments the campaign\'s <code>clicked_count</code> counter, then redirects to the original destination. Unsubscribe and tracking links are excluded from rewriting.', 'de' => '<strong>Link-Klick-Tracking:</strong> Alle externen Links in E-Mails werden über eine Umleitungs-Proxy-URL (<code>/track/click/{token}?to=...</code>) bereitgestellt. Beim Klick zeichnet das System den <code>clicked_at</code>-Zeitstempel auf und erhöht den <code>clicked_count</code>-Zähler der Kampagne, dann leitet es zum ursprünglichen Ziel weiter. Abmelde- und Tracking-Links sind vom Umschreiben ausgenommen.', 'ro' => '<strong>Urmărirea clicurilor pe linkuri:</strong> Toate linkurile externe din e-mailuri sunt servite printr-un URL proxy de redirecționare (<code>/track/click/{token}?to=...</code>). La clic, sistemul înregistrează timestamp-ul <code>clicked_at</code> și incrementează contorul <code>clicked_count</code> al campaniei, apoi redirecționează către destinația originală. Linkurile de dezabonare și urmărire sunt excluse din rescriere.', 'sk' => '<strong>Sledovanie kliknutí na odkazy:</strong> Všetky externé odkazy v e-mailoch sú obsluhované cez URL presmerúvaného proxy (<code>/track/click/{token}?to=...</code>). Pri kliknutí systém zaznamená časovú pečiatku <code>clicked_at</code> a zvýši počítadlo <code>clicked_count</code> kampane, potom presmeruje na pôvodný cieľ. Odkazy na odhlásenie a sledovacie odkazy sú vylúčené z prepisovania.'],
            ['hu' => '<strong>Megnyitások és kattintások megjelenítése a kampánylistában:</strong> Az Email kampányok táblázatában két új oszlop jelent meg: <em>Megnyitások</em> (abszolút szám + százalékos arány) és <em>Kattintások</em> — zöld kiemelő színnel. A statisztikák valós adatbázis-adatokon alapulnak.',
             'en'  => '<strong>Opens and clicks displayed in campaign list:</strong> Two new columns appear in the Email Campaigns table: <em>Opens</em> (absolute count + percentage rate) and <em>Clicks</em> — highlighted in green. Statistics are based on live database data.', 'de' => '<strong>Öffnungen und Klicks in der Kampagnenliste angezeigt:</strong> Zwei neue Spalten erscheinen in der E-Mail-Kampagnentabelle: <em>Öffnungen</em> (absolute Anzahl + prozentuale Rate) und <em>Klicks</em> — grün hervorgehoben. Statistiken basieren auf Live-Datenbankdaten.', 'ro' => '<strong>Deschideri și clicuri afișate în lista de campanii:</strong> Două coloane noi apar în tabelul Campanii de e-mail: <em>Deschideri</em> (număr absolut + rată procentuală) și <em>Clicuri</em> — evidențiate în verde. Statisticile se bazează pe date live din baza de date.', 'sk' => '<strong>Otvorenia a kliknutia zobrazené v zozname kampaní:</strong> V tabuľke E-mailových kampaní sa objavia dva nové stĺpce: <em>Otvorenia</em> (absolútny počet + percentuálna miera) a <em>Kliknutia</em> — zvýraznené zelenou farbou. Štatistiky sú založené na živých databázových dátach.'],
            ['hu' => '<strong>EmailTrackingService:</strong> Új <code>App\\Services\\EmailTrackingService</code> osztály, amely egységesen kezeli a link-csomagolást (<code>wrapLinks()</code>), a pixel-befűzést (<code>injectPixel()</code>) és a teljes folyamatot (<code>process()</code>). A base64-kódolt GIF konstansként tárolódik — sem fájlrendszer, sem HTTP-lekérés nem szükséges a pixelhez.',
             'en'  => '<strong>EmailTrackingService:</strong> New <code>App\\Services\\EmailTrackingService</code> class that uniformly handles link wrapping (<code>wrapLinks()</code>), pixel injection (<code>injectPixel()</code>) and the full pipeline (<code>process()</code>). The base64-encoded GIF is stored as a constant — no filesystem or HTTP request needed for the pixel.', 'de' => '<strong>EmailTrackingService:</strong> Neue Klasse <code>App\\Services\\EmailTrackingService</code>, die einheitlich Link-Wrapping (<code>wrapLinks()</code>), Pixel-Injektion (<code>injectPixel()</code>) und die gesamte Pipeline (<code>process()</code>) verarbeitet. Das base64-kodierte GIF wird als Konstante gespeichert — kein Dateisystem oder HTTP-Anfrage für das Pixel erforderlich.', 'ro' => '<strong>EmailTrackingService:</strong> Noua clasă <code>App\\Services\\EmailTrackingService</code> care gestionează uniform înfășurarea linkurilor (<code>wrapLinks()</code>), injectarea pixelilor (<code>injectPixel()</code>) și întreaga conductă (<code>process()</code>). GIF-ul codificat base64 este stocat ca o constantă — nu este necesară nicio cerere de sistem de fișiere sau HTTP pentru pixel.', 'sk' => '<strong>EmailTrackingService:</strong> Nová trieda <code>App\\Services\\EmailTrackingService</code>, ktorá jednotne spracúva zabalenie odkazov (<code>wrapLinks()</code>), injekciu pixelov (<code>injectPixel()</code>) a celý pipeline (<code>process()</code>). GIF zakódovaný v base64 je uložený ako konštanta — pre pixel nie je potrebný žiadny súborový systém ani HTTP požiadavka.'],
            ['hu' => '<strong>TrackingController (nyilvános végpontok):</strong> <code>GET /track/open/{token}</code> — visszaadja a GIF pixelt és frissíti az <code>opened_at</code> mezőt; <code>GET /track/click/{token}?to=URL</code> — átirányít a célra és frissíti a <code>clicked_at</code> mezőt. Biztonsági ellenőrzés: a <code>to</code> paraméter csak érvényes abszolút URL esetén kerül átirányításra (<code>FILTER_VALIDATE_URL</code>).',
             'en'  => '<strong>TrackingController (public endpoints):</strong> <code>GET /track/open/{token}</code> — returns the GIF pixel and updates the <code>opened_at</code> field; <code>GET /track/click/{token}?to=URL</code> — redirects to the destination and updates the <code>clicked_at</code> field. Security check: the <code>to</code> parameter is only redirected for valid absolute URLs (<code>FILTER_VALIDATE_URL</code>).', 'de' => '<strong>TrackingController (öffentliche Endpunkte):</strong> <code>GET /track/open/{token}</code> — gibt den GIF-Pixel zurück und aktualisiert das Feld <code>opened_at</code>; <code>GET /track/click/{token}?to=URL</code> — leitet zum Ziel weiter und aktualisiert das Feld <code>clicked_at</code>. Sicherheitsprüfung: Der Parameter <code>to</code> wird nur für gültige absolute URLs weitergeleitet (<code>FILTER_VALIDATE_URL</code>).', 'ro' => '<strong>TrackingController (puncte finale publice):</strong> <code>GET /track/open/{token}</code> — returnează pixelul GIF și actualizează câmpul <code>opened_at</code>; <code>GET /track/click/{token}?to=URL</code> — redirecționează către destinație și actualizează câmpul <code>clicked_at</code>. Verificare de securitate: parametrul <code>to</code> este redirecționat doar pentru URL-uri absolute valide (<code>FILTER_VALIDATE_URL</code>).', 'sk' => '<strong>TrackingController (verejné endpointy):</strong> <code>GET /track/open/{token}</code> — vráti GIF pixel a aktualizuje pole <code>opened_at</code>; <code>GET /track/click/{token}?to=URL</code> — presmeruje na cieľ a aktualizuje pole <code>clicked_at</code>. Bezpečnostná kontrola: parameter <code>to</code> je presmerovaný iba pre platné absolútne URL (<code>FILTER_VALIDATE_URL</code>).'],
        ],
    ],

    [
        'version' => 'v1.21.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 16.', 'en' => 'May 16, 2026', 'de' => '16. Mai 2026', 'ro' => '16 mai 2026', 'sk' => '16. mája 2026'],
        'items' => [
            ['hu' => '<strong>Egyérintéses leiratkozási oldal (publikus):</strong> Minden hírlevél-feliratkozónak egyedi <code>unsubscribe_token</code> kerül generálásra (meglévő rekordokra visszatöltő migráció is fut). Az emailekben megjelenik az <em>Leiratkozás / Unsubscribe</em> hivatkozás, amely az <code>/unsubscribe/{token}</code> oldalra vezet. Az oldal 4 állapotot kezel: aktív feliratkozó / leiratkozott / visszairatkozás opció / ismeretlen token.',
             'en'  => '<strong>One-click unsubscribe page (public):</strong> Every newsletter subscriber receives a unique <code>unsubscribe_token</code> (a backfill migration runs for existing records). Emails now include an <em>Unsubscribe</em> link pointing to <code>/unsubscribe/{token}</code>. The page handles 4 states: active subscriber / unsubscribed / re-subscribe option / unknown token.', 'de' => '<strong>Ein-Klick-Abmeldeseite (öffentlich):</strong> Jeder Newsletter-Abonnent erhält ein einzigartiges <code>unsubscribe_token</code> (eine Backfill-Migration läuft für bestehende Datensätze). E-Mails enthalten nun einen <em>Abmelden</em>-Link, der auf <code>/unsubscribe/{token}</code> zeigt. Die Seite verarbeitet 4 Zustände: aktiver Abonnent / abgemeldet / Wiederanmeldeoption / unbekanntes Token.', 'ro' => '<strong>Pagina de dezabonare cu un singur clic (publică):</strong> Fiecare abonat la newsletter primește un <code>unsubscribe_token</code> unic (o migrare de completare rulează pentru înregistrările existente). E-mailurile includ acum un link de <em>Dezabonare</em> care indică spre <code>/unsubscribe/{token}</code>. Pagina gestionează 4 stări: abonat activ / dezabonat / opțiune de reabonare / token necunoscut.', 'sk' => '<strong>Stránka odhlásenia jedným kliknutím (verejná):</strong> Každý odberateľ newslettera dostane jedinečný <code>unsubscribe_token</code> (pre existujúce záznamy prebehne dopĺňacia migrácia). E-maily teraz obsahujú odkaz <em>Odhlásiť sa</em> smerujúci na <code>/unsubscribe/{token}</code>. Stránka spracúva 4 stavy: aktívny odberateľ / odhlásený / možnosť opätovného prihlásenia / neznámy token.'],
            ['hu' => '<strong>RFC 8058 <code>List-Unsubscribe</code> fejlécek:</strong> Az elküldött emailek tartalmazzák a <code>List-Unsubscribe</code> és <code>List-Unsubscribe-Post: List-Unsubscribe=One-Click</code> fejléceket a Symfony <code>using:</code> callback-en keresztül. Ez lehetővé teszi a modernebb levelezők (Gmail, Outlook) számára, hogy egy kattintással leiratkozási gombot jelenítsenek meg.',
             'en'  => '<strong>RFC 8058 <code>List-Unsubscribe</code> headers:</strong> Sent emails now include <code>List-Unsubscribe</code> and <code>List-Unsubscribe-Post: List-Unsubscribe=One-Click</code> headers via a Symfony <code>using:</code> callback. This allows modern email clients (Gmail, Outlook) to render a one-click unsubscribe button.', 'de' => '<strong>RFC 8058 <code>List-Unsubscribe</code>-Header:</strong> Gesendete E-Mails enthalten nun <code>List-Unsubscribe</code>- und <code>List-Unsubscribe-Post: List-Unsubscribe=One-Click</code>-Header über einen Symfony <code>using:</code>-Callback. Dies ermöglicht modernen E-Mail-Clients (Gmail, Outlook) das Rendern einer Ein-Klick-Abmeldetaste.', 'ro' => '<strong>Anteturi RFC 8058 <code>List-Unsubscribe</code>:</strong> E-mailurile trimise includ acum anteturi <code>List-Unsubscribe</code> și <code>List-Unsubscribe-Post: List-Unsubscribe=One-Click</code> printr-un callback Symfony <code>using:</code>. Aceasta permite clienților de e-mail moderni (Gmail, Outlook) să afișeze un buton de dezabonare cu un singur clic.', 'sk' => '<strong>RFC 8058 hlavičky <code>List-Unsubscribe</code>:</strong> Odoslané e-maily teraz obsahujú hlavičky <code>List-Unsubscribe</code> a <code>List-Unsubscribe-Post: List-Unsubscribe=One-Click</code> cez Symfony callback <code>using:</code>. To umožňuje moderným e-mailovým klientom (Gmail, Outlook) zobraziť tlačidlo odhlásenia jedným kliknutím.'],
            ['hu' => '<strong>Visszairatkozási lehetőség:</strong> A leiratkozott állapotban az oldal egy <em>Visszairatkozás</em> gombot is megjelenít. A visszairatkozás egy külön POST végponton (<code>/unsubscribe/{token}/resubscribe</code>) keresztül valósul meg, és az <code>is_subscribed</code> értéket <code>true</code>-ra állítja.',
             'en'  => '<strong>Re-subscribe option:</strong> On the unsubscribed state, the page also shows a <em>Re-subscribe</em> button. Re-subscribing is handled through a separate POST endpoint (<code>/unsubscribe/{token}/resubscribe</code>) that sets <code>is_subscribed</code> back to <code>true</code>.', 'de' => '<strong>Wiederanmeldeoption:</strong> Im abgemeldeten Zustand zeigt die Seite auch eine <em>Erneut anmelden</em>-Schaltfläche. Die Wiederanmeldung wird über einen separaten POST-Endpunkt (<code>/unsubscribe/{token}/resubscribe</code>) verarbeitet, der <code>is_subscribed</code> wieder auf <code>true</code> setzt.', 'ro' => '<strong>Opțiunea de reabonare:</strong> În starea dezabonat, pagina afișează și un buton <em>Reabonare</em>. Reabonarea este gestionată printr-un endpoint POST separat (<code>/unsubscribe/{token}/resubscribe</code>) care setează <code>is_subscribed</code> înapoi la <code>true</code>.', 'sk' => '<strong>Možnosť opätovného prihlásenia:</strong> V stave odhlásenia stránka zobrazuje aj tlačidlo <em>Opätovne sa prihlásiť</em>. Opätovné prihlásenie sa spracúva cez samostatný POST endpoint (<code>/unsubscribe/{token}/resubscribe</code>), ktorý nastaví <code>is_subscribed</code> späť na <code>true</code>.'],
        ],
    ],

    [
        'version' => 'v1.20.0',
        'badge'   => [
            'text'  => ['hu' => 'Új modul', 'en' => 'New module', 'de' => 'Neues Modul', 'ro' => 'Modul nou', 'sk' => 'Nový modul'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 16.', 'en' => 'May 16, 2026', 'de' => '16. Mai 2026', 'ro' => '16 mai 2026', 'sk' => '16. mája 2026'],
        'items' => [
            ['hu' => '<strong>Automatizált csepp (drip) kampány modul:</strong> Új <code>/admin/drip-campaigns</code> oldal. Minden drip kampányhoz tetszőleges számú lépés adható meg — tárgy, feladó, HTML tartalom, és az előző lépéstől eltelt napok száma. Indítók: <em>Manuális</em>, <em>Csoporthoz csatlakozás</em>, <em>Tag hozzáadás</em>.',
             'en'  => '<strong>Automated drip campaign module:</strong> New <code>/admin/drip-campaigns</code> page. Each drip campaign supports an unlimited number of steps — subject, sender, HTML content, and delay in days from the previous step. Triggers: <em>Manual</em>, <em>Group join</em>, <em>Tag added</em>.', 'de' => '<strong>Automatisiertes Drip-Kampagnen-Modul:</strong> Neue Seite <code>/admin/drip-campaigns</code>. Jede Drip-Kampagne unterstützt eine unbegrenzte Anzahl von Schritten — Betreff, Absender, HTML-Inhalt und Verzögerung in Tagen vom vorherigen Schritt. Auslöser: <em>Manuell</em>, <em>Gruppe beitreten</em>, <em>Tag hinzugefügt</em>.', 'ro' => '<strong>Modul de campanie drip automatizată:</strong> Noua pagină <code>/admin/drip-campaigns</code>. Fiecare campanie drip suportă un număr nelimitat de pași — subiect, expeditor, conținut HTML și întârziere în zile față de pasul anterior. Declanșatoare: <em>Manual</em>, <em>Alăturare la grup</em>, <em>Tag adăugat</em>.', 'sk' => '<strong>Modul automatizovanej drip kampane:</strong> Nová stránka <code>/admin/drip-campaigns</code>. Každá drip kampaň podporuje neobmedzený počet krokov — predmet, odosielateľ, HTML obsah a oneskorenie v dňoch od predchádzajúceho kroku. Spúšťače: <em>Manuálne</em>, <em>Vstup do skupiny</em>, <em>Pridaný tag</em>.'],
            ['hu' => '<strong>Drip beiratkozás és feldolgozás:</strong> Kontaktok manuálisan (admin gomb) vagy automatikusan (trigger) iratkozhatnak be egy drip kampányba. Az <code>drip:process</code> Artisan parancs 15 percenként fut: megkeresi az esedékes beiratkozásokat, elküldi a következő lépést, és beállítja a következő küldési időpontot. A kampány végeztével a beiratkozás <em>completed</em> státuszt kap.',
             'en'  => '<strong>Drip enrollment and processing:</strong> Contacts can enroll in a drip campaign manually (admin button) or automatically (via trigger). The <code>drip:process</code> Artisan command runs every 15 minutes: it finds due enrollments, sends the next step, and sets the next send time. When the campaign ends, the enrollment receives <em>completed</em> status.', 'de' => '<strong>Drip-Einschreibung und -Verarbeitung:</strong> Kontakte können sich manuell (Admin-Schaltfläche) oder automatisch (über Auslöser) in eine Drip-Kampagne einschreiben. Der Artisan-Befehl <code>drip:process</code> läuft alle 15 Minuten: Er findet fällige Einschreibungen, sendet den nächsten Schritt und setzt die nächste Sendezeit. Wenn die Kampagne endet, erhält die Einschreibung den Status <em>abgeschlossen</em>.', 'ro' => '<strong>Înregistrare și procesare drip:</strong> Contactele se pot înscrie într-o campanie drip manual (buton de admin) sau automat (prin declanșator). Comanda Artisan <code>drip:process</code> rulează la fiecare 15 minute: găsește înregistrările scadente, trimite pasul următor și setează ora de trimitere următoare. Când campania se termină, înregistrarea primește starea <em>finalizat</em>.', 'sk' => '<strong>Registrácia a spracovanie drip:</strong> Kontakty sa môžu zaregistrovať do drip kampane manuálne (tlačidlo admina) alebo automaticky (cez spúšťač). Artisan príkaz <code>drip:process</code> beží každých 15 minút: nájde splatné registrácie, odošle ďalší krok a nastaví nasledujúci čas odoslania. Keď kampaň skončí, registrácia dostane stav <em>dokončené</em>.'],
            ['hu' => '<strong>Drip kampány admin felület:</strong> A részletoldalon 4 statisztikai kártya (aktív / lezárt / lemondott beiratkozások, összes lépés), szerkeszthető lépéslista modal alapon, beiratkozások listája emberenként és lépésenként. Kampány aktiválása / szüneteltetése egy kattintással.',
             'en'  => '<strong>Drip campaign admin interface:</strong> The detail page shows 4 stat cards (active / completed / cancelled enrollments, total steps), editable step list via modals, and enrollments list per person and per step. Campaign activation / pausing with a single click.', 'de' => '<strong>Drip-Kampagnen-Admin-Oberfläche:</strong> Die Detailseite zeigt 4 Statistikkarten (aktive / abgeschlossene / stornierte Einschreibungen, Gesamtschritte), bearbeitbare Schrittliste über Modals und Einschreibungsliste pro Person und Schritt. Kampagnenaktivierung / -pause mit einem Klick.', 'ro' => '<strong>Interfața de administrare a campaniei drip:</strong> Pagina de detalii afișează 4 carduri de statistici (înregistrări active / finalizate / anulate, total pași), lista de pași editabilă prin modals și lista de înregistrări per persoană și per pas. Activarea / întreruperea campaniei cu un singur clic.', 'sk' => '<strong>Administrátorské rozhranie drip kampane:</strong> Stránka s podrobnosťami zobrazuje 4 štatistické karty (aktívne / dokončené / zrušené registrácie, celkový počet krokov), upraviteľný zoznam krokov cez modals a zoznam registrácií na osobu a krok. Aktivácia / pozastavenie kampane jedným kliknutím.'],
            ['hu' => '<strong>Adatbázis-séma:</strong> Három új tábla: <code>drip_campaigns</code> (kampány fejadatok, trigger típus és cél-csoport/tag), <code>drip_steps</code> (lépések pozíció szerint rendezve), <code>drip_enrollments</code> (beiratkozások státusszal, <code>next_send_at</code> indexszel), valamint <code>drip_sends</code> (küldési nyomkövetés, tracking tokennel).',
             'en'  => '<strong>Database schema:</strong> Three new tables: <code>drip_campaigns</code> (campaign header, trigger type and target group/tag), <code>drip_steps</code> (steps ordered by position), <code>drip_enrollments</code> (enrollments with status, <code>next_send_at</code> index), and <code>drip_sends</code> (send tracking with tracking token).', 'de' => '<strong>Datenbankschema:</strong> Drei neue Tabellen: <code>drip_campaigns</code> (Kampagnenkopf, Auslösertyp und Zielgruppe/Tag), <code>drip_steps</code> (nach Position geordnete Schritte), <code>drip_enrollments</code> (Einschreibungen mit Status, <code>next_send_at</code>-Index) und <code>drip_sends</code> (Versand-Tracking mit Tracking-Token).', 'ro' => '<strong>Schema bazei de date:</strong> Trei tabele noi: <code>drip_campaigns</code> (antetul campaniei, tipul declanșatorului și grupul/tag-ul țintă), <code>drip_steps</code> (pași ordonați după poziție), <code>drip_enrollments</code> (înregistrări cu stare, index <code>next_send_at</code>) și <code>drip_sends</code> (urmărirea trimiterilor cu token de urmărire).', 'sk' => '<strong>Schéma databázy:</strong> Tri nové tabuľky: <code>drip_campaigns</code> (hlavička kampane, typ spúšťača a cieľová skupina/tag), <code>drip_steps</code> (kroky zoradené podľa pozície), <code>drip_enrollments</code> (registrácie so stavom, index <code>next_send_at</code>) a <code>drip_sends</code> (sledovanie odosielania so sledovacím tokenom).'],
        ],
    ],

    [
        'version' => 'v1.19.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 16.', 'en' => 'May 16, 2026', 'de' => '16. Mai 2026', 'ro' => '16 mai 2026', 'sk' => '16. mája 2026'],
        'items' => [
            ['hu' => '<strong>Kampány célcsoport szegmentálás:</strong> A kampány létrehozás és szerkesztés modalban megjelent a <em>Célcsoport</em> szekció. Az admin négy opció közül választhat: <em>Összes hírlevél feliratkozó</em>, <em>Csoport tagjai</em> (több csoport is kijelölhető), <em>Tagelt kontaktok</em> (több tag), <em>Tag státusz szerint</em> (több státusz). A szűrőkombináció JSON formában tárolódik az <code>email_campaigns.segment_filters</code> oszlopban.',
             'en'  => '<strong>Campaign audience segmentation:</strong> A <em>Audience</em> section appeared in the campaign create and edit modal. Admins can choose from four options: <em>All newsletter subscribers</em>, <em>Group members</em> (multiple groups selectable), <em>Tagged contacts</em> (multiple tags), <em>By member status</em> (multiple statuses). The filter combination is stored as JSON in the <code>email_campaigns.segment_filters</code> column.', 'de' => '<strong>Kampagnenzielgruppen-Segmentierung:</strong> Ein Abschnitt <em>Zielgruppe</em> erschien im Kampagnenerstellungs- und -bearbeitungsmodal. Admins können aus vier Optionen wählen: <em>Alle Newsletter-Abonnenten</em>, <em>Gruppenmitglieder</em> (mehrere Gruppen auswählbar), <em>Getaggte Kontakte</em> (mehrere Tags), <em>Nach Mitgliedsstatus</em> (mehrere Status). Die Filterkombination wird als JSON in der Spalte <code>email_campaigns.segment_filters</code> gespeichert.', 'ro' => '<strong>Segmentarea publicului campaniei:</strong> O secțiune <em>Public</em> a apărut în modalul de creare și editare a campaniei. Administratorii pot alege din patru opțiuni: <em>Toți abonații la newsletter</em>, <em>Membri ai grupului</em> (mai multe grupuri selectabile), <em>Contacte cu tag-uri</em> (mai multe tag-uri), <em>După statutul membrului</em> (mai multe statute). Combinația de filtre este stocată ca JSON în coloana <code>email_campaigns.segment_filters</code>.', 'sk' => '<strong>Segmentácia publika kampane:</strong> V modálnom okne vytvorenia a úpravy kampane sa objavila sekcia <em>Publikum</em>. Správcovia si môžu vybrať zo štyroch možností: <em>Všetci odberatelia newslettera</em>, <em>Členovia skupiny</em> (vyberateľné viacero skupín), <em>Kontakty s tagom</em> (viacero tagov), <em>Podľa stavu člena</em> (viacero stavov). Kombinácia filtrov sa ukladá ako JSON do stĺpca <code>email_campaigns.segment_filters</code>.'],
            ['hu' => '<strong>Élő fogadószám előnézet:</strong> Szegmentációs beállítás módosításakor az oldal AJAX-on keresztül (<code>GET /admin/campaigns/recipient-count</code>) valós időben kéri le a becsült fogadók számát, és 500 ms-os debounce-szal jeleníti meg. A kampánylistában megjelent a <em>Szegmens</em> oszlop a típus jelzésével.',
             'en'  => '<strong>Live recipient count preview:</strong> When the segmentation setting changes, the page fetches the estimated recipient count in real time via AJAX (<code>GET /admin/campaigns/recipient-count</code>) with a 500 ms debounce, and displays it immediately. A <em>Segment</em> column appeared in the campaign list indicating the type.', 'de' => '<strong>Live-Empfängeranzahl-Vorschau:</strong> Wenn sich die Segmentierungseinstellung ändert, ruft die Seite die geschätzte Empfängeranzahl in Echtzeit über AJAX (<code>GET /admin/campaigns/recipient-count</code>) mit einem 500-ms-Debounce ab und zeigt sie sofort an. In der Kampagnenliste erschien eine Spalte <em>Segment</em> mit Angabe des Typs.', 'ro' => '<strong>Previzualizarea în timp real a numărului de destinatari:</strong> Când setarea de segmentare se modifică, pagina preia numărul estimat de destinatari în timp real prin AJAX (<code>GET /admin/campaigns/recipient-count</code>) cu un debounce de 500 ms și îl afișează imediat. O coloană <em>Segment</em> a apărut în lista de campanii indicând tipul.', 'sk' => '<strong>Živý náhľad počtu príjemcov:</strong> Keď sa zmení nastavenie segmentácie, stránka načíta odhadovaný počet príjemcov v reálnom čase cez AJAX (<code>GET /admin/campaigns/recipient-count</code>) s 500 ms debouncingom a zobrazí ho okamžite. V zozname kampaní sa objavil stĺpec <em>Segment</em> s uvedením typu.'],
            ['hu' => '<strong><code>buildRecipientsQuery()</code> metódus az <code>EmailCampaign</code> modellen:</strong> Egységes lekérdezés-építő, amely a <code>segment_filters</code> JSON alapján szűri a feliratkozott, érvényes email-lel rendelkező kontaktokat — csoportszűrő esetén <code>whereHas(\'groups\')</code>, tagszűrőnél <code>whereHas(\'tags\')</code>, státuszszűrőnél <code>whereIn(\'status\')</code>.',
             'en'  => '<strong><code>buildRecipientsQuery()</code> method on <code>EmailCampaign</code> model:</strong> A unified query builder that filters subscribed contacts with valid emails based on the <code>segment_filters</code> JSON — using <code>whereHas(\'groups\')</code> for group filter, <code>whereHas(\'tags\')</code> for tag filter, <code>whereIn(\'status\')</code> for status filter.', 'de' => '<strong><code>buildRecipientsQuery()</code>-Methode am <code>EmailCampaign</code>-Modell:</strong> Ein einheitlicher Query-Builder, der abonnierte Kontakte mit gültigen E-Mails basierend auf dem <code>segment_filters</code>-JSON filtert — mit <code>whereHas(\'groups\')</code> für Gruppenfilter, <code>whereHas(\'tags\')</code> für Tag-Filter, <code>whereIn(\'status\')</code> für Statusfilter.', 'ro' => '<strong>Metoda <code>buildRecipientsQuery()</code> pe modelul <code>EmailCampaign</code>:</strong> Un constructor de interogări unificat care filtrează contactele abonate cu e-mailuri valide pe baza JSON-ului <code>segment_filters</code> — folosind <code>whereHas(\'groups\')</code> pentru filtrul de grup, <code>whereHas(\'tags\')</code> pentru filtrul de tag, <code>whereIn(\'status\')</code> pentru filtrul de stare.', 'sk' => '<strong>Metóda <code>buildRecipientsQuery()</code> na modeli <code>EmailCampaign</code>:</strong> Unifikovaný tvorca dotazov, ktorý filtruje prihlásených kontaktov s platnými e-mailmi na základe JSON <code>segment_filters</code> — pomocou <code>whereHas(\'groups\')</code> pre filter skupiny, <code>whereHas(\'tags\')</code> pre filter tagov, <code>whereIn(\'status\')</code> pre filter stavu.'],
        ],
    ],

    [
        'version' => 'v1.18.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 16.', 'en' => 'May 16, 2026', 'de' => '16. Mai 2026', 'ro' => '16 mai 2026', 'sk' => '16. mája 2026'],
        'items' => [
            ['hu' => '<strong>Email sablonkönyvtár:</strong> Új <code>/admin/email-templates</code> oldal, amely kártyás elrendezésben mutatja a beépített (<em>Minimál, Hírlevél, Bejelentés, Promóciós</em>) és az egyéni sablonokat. Minden sablon szerkeszthető, előnézhető (iframe modal) és törlhető (kivéve a beépítetteket).',
             'en'  => '<strong>Email template library:</strong> New <code>/admin/email-templates</code> page displaying built-in (<em>Minimal, Newsletter, Announcement, Promotional</em>) and custom templates in card layout. Every template can be edited, previewed (iframe modal) and deleted (except built-ins).', 'de' => '<strong>E-Mail-Vorlagenbibliothek:</strong> Neue Seite <code>/admin/email-templates</code> mit integrierten (<em>Minimal, Newsletter, Ankündigung, Werbung</em>) und benutzerdefinierten Vorlagen im Kartenlayout. Jede Vorlage kann bearbeitet, vorgeschaut (iframe-Modal) und gelöscht werden (außer integrierten).', 'ro' => '<strong>Biblioteca de șabloane de e-mail:</strong> Noua pagină <code>/admin/email-templates</code> afișând șabloane integrate (<em>Minimal, Newsletter, Anunț, Promoțional</em>) și personalizate în aspect card. Fiecare șablon poate fi editat, previzualizat (modal iframe) și șters (cu excepția celor integrate).', 'sk' => '<strong>Knižnica e-mailových šablón:</strong> Nová stránka <code>/admin/email-templates</code> zobrazujúca vstavané (<em>Minimálna, Newsletter, Oznámenie, Propagačná</em>) a vlastné šablóny v rozložení kariet. Každú šablónu je možné upraviť, zobraziť náhľad (iframe modal) a odstrániť (okrem vstavaných).'],
            ['hu' => '<strong>Sablon betöltése a kampányszerkesztőbe:</strong> A kampány létrehozás és szerkesztés modalban megjelent a <em>„Sablon betöltése"</em> gomb. Megnyit egy sablonválasztó modalt, amelyből egy kattintással a kiválasztott sablon HTML tartalma betöltődik a szerkesztőbe. Az összes elérhető sablon listaszerűen és részletes előnézettel tekinthető meg.',
             'en'  => '<strong>Loading a template into the campaign editor:</strong> A <em>"Use template"</em> button appeared in the campaign create and edit modal. It opens a template picker modal, from which a single click loads the selected template\'s HTML content into the editor. All available templates are listed with a detailed preview.', 'de' => '<strong>Vorlage in den Kampagneneditor laden:</strong> Im Kampagnenerstellungs- und -bearbeitungsmodal erschien eine Schaltfläche <em>"Vorlage verwenden"</em>. Sie öffnet ein Vorlagenauswahl-Modal, aus dem ein einziger Klick den HTML-Inhalt der ausgewählten Vorlage in den Editor lädt. Alle verfügbaren Vorlagen werden mit einer detaillierten Vorschau aufgelistet.', 'ro' => '<strong>Încărcarea unui șablon în editorul de campanie:</strong> Un buton <em>"Folosiți șablonul"</em> a apărut în modalul de creare și editare a campaniei. Acesta deschide un modal de selectare a șablonului, din care un singur clic încarcă conținutul HTML al șablonului selectat în editor. Toate șabloanele disponibile sunt listate cu o previzualizare detaliată.', 'sk' => '<strong>Načítanie šablóny do editora kampane:</strong> V modálnom okne vytvorenia a úpravy kampane sa objavilo tlačidlo <em>"Použiť šablónu"</em>. Otvára modálny výber šablóny, z ktorého jediné kliknutie načíta HTML obsah vybranej šablóny do editora. Všetky dostupné šablóny sú uvedené s podrobným náhľadom.'],
            ['hu' => '<strong>Beépített sablonok (seeder):</strong> A telepítéskor 4 professzionális beépített sablon kerül az adatbázisba automatikusan, amelyek szervezeti arculathoz testreszabhatók. Az <code>email_templates</code> tábla tartalmazza: <code>name</code>, <code>description</code>, <code>category</code>, <code>body_html</code>, <code>is_system</code> (boolean) mezőket.',
             'en'  => '<strong>Built-in templates (seeder):</strong> At installation, 4 professional built-in templates are automatically inserted into the database and can be customized for organizational branding. The <code>email_templates</code> table contains: <code>name</code>, <code>description</code>, <code>category</code>, <code>body_html</code>, <code>is_system</code> (boolean) columns.', 'de' => '<strong>Integrierte Vorlagen (Seeder):</strong> Bei der Installation werden 4 professionelle integrierte Vorlagen automatisch in die Datenbank eingefügt und können für das Organisationsbranding angepasst werden. Die Tabelle <code>email_templates</code> enthält: Spalten <code>name</code>, <code>description</code>, <code>category</code>, <code>body_html</code>, <code>is_system</code> (boolean).', 'ro' => '<strong>Șabloane integrate (seeder):</strong> La instalare, 4 șabloane integrate profesionale sunt inserate automat în baza de date și pot fi personalizate pentru identitatea organizației. Tabelul <code>email_templates</code> conține: coloanele <code>name</code>, <code>description</code>, <code>category</code>, <code>body_html</code>, <code>is_system</code> (boolean).', 'sk' => '<strong>Vstavané šablóny (seeder):</strong> Pri inštalácii sú 4 profesionálne vstavané šablóny automaticky vložené do databázy a môžu byť prispôsobené pre firemný branding organizácie. Tabuľka <code>email_templates</code> obsahuje: stĺpce <code>name</code>, <code>description</code>, <code>category</code>, <code>body_html</code>, <code>is_system</code> (boolean).'],
        ],
    ],

    [
        'version' => 'v1.17.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 16.', 'en' => 'May 16, 2026', 'de' => '16. Mai 2026', 'ro' => '16 mai 2026', 'sk' => '16. mája 2026'],
        'items' => [
            ['hu' => '<strong>Adomány export könyveléshez (CSV, XLSX, PDF):</strong> Az Adományok oldalon megjelent az <em>Export</em> gomb. Az exportálás szűrhető: kezdési és befejezési dátum, pénznem. Három formátum érhető el: CSV (UTF-8 BOM, pontosvesszős), Excel (XLSX, félkövér fejléc) és PDF (táblázatos elrendezés). A <code>phpoffice/phpspreadsheet</code> kezeli az XLSX-t, a <code>dompdf/dompdf</code> a PDF-t.',
             'en'  => '<strong>Donation export for accounting (CSV, XLSX, PDF):</strong> An <em>Export</em> button appeared on the Donations page. Export is filterable by start date, end date and currency. Three formats are available: CSV (UTF-8 BOM, semicolon-separated), Excel (XLSX, bold header) and PDF (tabular layout). <code>phpoffice/phpspreadsheet</code> handles XLSX; <code>dompdf/dompdf</code> handles PDF.', 'de' => '<strong>Adomány-Export für die Buchhaltung (CSV, XLSX, PDF):</strong> Auf der Spendenpage erschien eine Schaltfläche <em>Exportieren</em>. Der Export ist nach Startdatum, Enddatum und Währung filterbar. Drei Formate sind verfügbar: CSV (UTF-8 BOM, durch Semikolon getrennt), Excel (XLSX, fetter Header) und PDF (tabellarisches Layout). <code>phpoffice/phpspreadsheet</code> verarbeitet XLSX; <code>dompdf/dompdf</code> verarbeitet PDF.', 'ro' => '<strong>Export donații pentru contabilitate (CSV, XLSX, PDF):</strong> Un buton <em>Export</em> a apărut pe pagina Donații. Exportul este filtrabil după dată de început, dată de sfârșit și monedă. Trei formate sunt disponibile: CSV (UTF-8 BOM, separate prin punct și virgulă), Excel (XLSX, antet îngroșat) și PDF (aspect tabelar). <code>phpoffice/phpspreadsheet</code> gestionează XLSX; <code>dompdf/dompdf</code> gestionează PDF.', 'sk' => '<strong>Export darov pre účtovníctvo (CSV, XLSX, PDF):</strong> Na stránke Dary sa objavilo tlačidlo <em>Exportovať</em>. Export je filtrovateľný podľa dátumu začiatku, dátumu konca a meny. Sú k dispozícii tri formáty: CSV (UTF-8 BOM, oddelené bodkočiarkou), Excel (XLSX, tučná hlavička) a PDF (tabuľkový layout). <code>phpoffice/phpspreadsheet</code> spracúva XLSX; <code>dompdf/dompdf</code> spracúva PDF.'],
            ['hu' => '<strong>Exportált mezők:</strong> Dátum, Kapcsolat neve, Email, Összeg, Pénznem, Fizetési módszer, Státusz, Tranzakció ID, Kampány, Megjegyzés — ezek a könyvelési feldolgozáshoz szükséges legfontosabb adatok kerülnek exportálásra.',
             'en'  => '<strong>Exported fields:</strong> Date, Contact name, Email, Amount, Currency, Payment method, Status, Transaction ID, Campaign, Notes — these essential data points needed for accounting processing are exported.', 'de' => '<strong>Exportierte Felder:</strong> Datum, Kontaktname, E-Mail, Betrag, Währung, Zahlungsmethode, Status, Transaktions-ID, Kampagne, Notizen — diese wesentlichen Datenpunkte für die Buchhalterverarbeitung werden exportiert.', 'ro' => '<strong>Câmpuri exportate:</strong> Dată, Numele contactului, E-mail, Sumă, Monedă, Metodă de plată, Stare, ID tranzacție, Campanie, Note — aceste puncte de date esențiale necesare pentru procesarea contabilă sunt exportate.', 'sk' => '<strong>Exportované polia:</strong> Dátum, Meno kontaktu, E-mail, Suma, Mena, Spôsob platby, Stav, ID transakcie, Kampaň, Poznámky — tieto základné dátové body potrebné pre účtovné spracovanie sú exportované.'],
        ],
    ],

    [
        'version' => 'v1.16.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 16.', 'en' => 'May 16, 2026', 'de' => '16. Mai 2026', 'ro' => '16 mai 2026', 'sk' => '16. mája 2026'],
        'items' => [
            ['hu' => '<strong>Nyilvános online adományozási oldal:</strong> A <code>/donate</code> URL bejelentkezés nélkül elérhető adományozási űrlapot jelenít meg — adományozó neve, email, összeg, pénznem, megjegyzés mezőkkel. Sikeres küldés után visszaigazoló email megy az adományozónak (<em>DonationReceiptMail</em>), és megjelenik egy köszönő oldal (<code>/donate/thanks/{token}</code>).',
             'en'  => '<strong>Public online donation form:</strong> The <code>/donate</code> URL displays a donation form accessible without login — with donor name, email, amount, currency and notes fields. On successful submission, a receipt email is sent to the donor (<em>DonationReceiptMail</em>), and a thank-you page appears (<code>/donate/thanks/{token}</code>).', 'de' => '<strong>Öffentliches Online-Spendenformular:</strong> Die URL <code>/donate</code> zeigt ein Spendenformular an, das ohne Anmeldung zugänglich ist — mit Feldern für Spendername, E-Mail, Betrag, Währung und Notizen. Bei erfolgreicher Einreichung wird eine Quittungs-E-Mail an den Spender gesendet (<em>DonationReceiptMail</em>), und eine Dankesseite erscheint (<code>/donate/thanks/{token}</code>).', 'ro' => '<strong>Formular de donații online public:</strong> URL-ul <code>/donate</code> afișează un formular de donații accesibil fără autentificare — cu câmpuri pentru numele donatorului, e-mail, sumă, monedă și note. La depunerea cu succes, un e-mail de chitanță este trimis donatorului (<em>DonationReceiptMail</em>), și apare o pagină de mulțumire (<code>/donate/thanks/{token}</code>).', 'sk' => '<strong>Verejný online formulár darov:</strong> URL <code>/donate</code> zobrazuje formulár darov dostupný bez prihlásenia — s poliami pre meno darcu, e-mail, sumu, menu a poznámky. Pri úspešnom odoslaní sa darcovi pošle e-mail s potvrdením (<em>DonationReceiptMail</em>) a zobrazí sa stránka s poďakovaním (<code>/donate/thanks/{token}</code>).'],
            ['hu' => '<strong>Online fizetés Stripe / Barion integrációval:</strong> A nyilvános adományozási oldal támogatja a bankkártyás fizetést. Stripe esetén a rendszer egy Checkout Session-t hoz létre, és a visszatérési URL-en (<code>/payment/donation/stripe/success/{token}</code>) igazolja a fizetést. Barion integráció szintén elérhető (<code>/payment/donation/barion/callback/{token}</code>).',
             'en'  => '<strong>Online payment with Stripe / Barion integration:</strong> The public donation form supports card payments. For Stripe, the system creates a Checkout Session and verifies the payment on the return URL (<code>/payment/donation/stripe/success/{token}</code>). Barion integration is also available (<code>/payment/donation/barion/callback/{token}</code>).', 'de' => '<strong>Online-Zahlung mit Stripe / Barion-Integration:</strong> Das öffentliche Spendenformular unterstützt Kartenzahlungen. Für Stripe erstellt das System eine Checkout-Session und überprüft die Zahlung auf der Rückgabe-URL (<code>/payment/donation/stripe/success/{token}</code>). Barion-Integration ist ebenfalls verfügbar (<code>/payment/donation/barion/callback/{token}</code>).', 'ro' => '<strong>Plată online cu integrare Stripe / Barion:</strong> Formularul public de donații suportă plăți cu card. Pentru Stripe, sistemul creează o Sesiune de Checkout și verifică plata pe URL-ul de returnare (<code>/payment/donation/stripe/success/{token}</code>). Integrarea Barion este de asemenea disponibilă (<code>/payment/donation/barion/callback/{token}</code>).', 'sk' => '<strong>Online platba s integráciou Stripe / Barion:</strong> Verejný formulár darov podporuje platby kartou. Pre Stripe systém vytvorí reláciu Checkout a overí platbu na návratovej URL (<code>/payment/donation/stripe/success/{token}</code>). Integrácia Barion je tiež dostupná (<code>/payment/donation/barion/callback/{token}</code>).'],
        ],
    ],

    [
        'version' => 'v1.15.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 16.', 'en' => 'May 16, 2026', 'de' => '16. Mai 2026', 'ro' => '16 mai 2026', 'sk' => '16. mája 2026'],
        'items' => [
            ['hu' => '<strong>Feladat megjegyzések:</strong> Minden feladathoz szöveges megjegyzések fűzhetők, megjelenítve az időpontot és a beküldő felhasználót. A megjegyzések szerkeszthetők és törölhetők. Az adatokat a <code>task_comments</code> tábla tárolja.',
             'en'  => '<strong>Task comments:</strong> Text comments can be added to every task, showing the timestamp and the submitting user. Comments can be edited and deleted. Data is stored in the <code>task_comments</code> table.', 'de' => '<strong>Aufgabenkommentare:</strong> Zu jeder Aufgabe können Textkommentare hinzugefügt werden, die den Zeitstempel und den einsendenden Benutzer anzeigen. Kommentare können bearbeitet und gelöscht werden. Daten werden in der Tabelle <code>task_comments</code> gespeichert.', 'ro' => '<strong>Comentarii la sarcini:</strong> Comentarii text pot fi adăugate la fiecare sarcină, afișând timestamp-ul și utilizatorul care le-a trimis. Comentariile pot fi editate și șterse. Datele sunt stocate în tabelul <code>task_comments</code>.', 'sk' => '<strong>Komentáre k úlohám:</strong> K každej úlohe je možné pridať textové komentáre zobrazujúce časovú pečiatku a odosielateľa. Komentáre je možné upravovať a mazať. Dáta sú uložené v tabuľke <code>task_comments</code>.'],
            ['hu' => '<strong>Feladat fájlmellékletek:</strong> Feladatokhoz fájlok csatolhatók (max. 10 MB) — a <code>task_attachments</code> tábla és a Spatie MediaLibrary kezeli a tárolást. A melléklet neve, mérete és feltöltési ideje megjelenik a feladat részletoldalán; letölthető és törölhető.',
             'en'  => '<strong>Task file attachments:</strong> Files can be attached to tasks (max. 10 MB) — the <code>task_attachments</code> table and Spatie MediaLibrary handle storage. The attachment name, size and upload time appear on the task detail page; files are downloadable and deletable.', 'de' => '<strong>Aufgaben-Dateianhänge:</strong> Dateien können an Aufgaben angehängt werden (max. 10 MB) — die Tabelle <code>task_attachments</code> und Spatie MediaLibrary verwalten die Speicherung. Name, Größe und Upload-Zeit des Anhangs erscheinen auf der Aufgabendetailseite; Dateien sind herunterladbar und löschbar.', 'ro' => '<strong>Atașamente de fișiere la sarcini:</strong> Fișierele pot fi atașate la sarcini (max. 10 MB) — tabelul <code>task_attachments</code> și Spatie MediaLibrary gestionează stocarea. Numele atașamentului, dimensiunea și ora de încărcare apar pe pagina de detalii a sarcinii; fișierele sunt descărcabile și ștergibile.', 'sk' => '<strong>Prílohy súborov k úlohám:</strong> K úlohám je možné priložiť súbory (max. 10 MB) — tabuľka <code>task_attachments</code> a Spatie MediaLibrary spravujú úložisko. Názov prílohy, veľkosť a čas nahrávania sa zobrazujú na stránke s podrobnosťami úlohy; súbory sú stiahnuteľné a vymazateľné.'],
            ['hu' => '<strong>Gantt-stílusú idővonal nézet (Projektek):</strong> A projekt részletoldalán megjelent egy <em>Gantt nézet</em> fül. A nézet az összes projekt-feladatot az idővonalán helyezi el — vízszintes sáv mutatja a kezdési és befejezési dátumot, határidőn túl esetén piros kiemelés.',
             'en'  => '<strong>Gantt-style timeline view (Projects):</strong> A <em>Gantt view</em> tab appeared on the project detail page. The view places all project tasks on a timeline — a horizontal bar shows the start and end date, with red highlighting for overdue tasks.', 'de' => '<strong>Gantt-artige Zeitachsenansicht (Projekte):</strong> Auf der Projektdetailseite erschien ein Tab <em>Gantt-Ansicht</em>. Die Ansicht platziert alle Projektaufgaben auf einer Zeitachse — ein horizontaler Balken zeigt das Start- und Enddatum, mit roter Hervorhebung für überfällige Aufgaben.', 'ro' => '<strong>Vedere cronologică în stil Gantt (Proiecte):</strong> Un tab <em>Vedere Gantt</em> a apărut pe pagina de detalii a proiectului. Vederea plasează toate sarcinile proiectului pe o cronologie — un bar orizontal arată data de început și de sfârșit, cu evidențiere roșie pentru sarcinile întârziate.', 'sk' => '<strong>Zobrazenie časovej osi v štýle Gantt (Projekty):</strong> Na stránke s podrobnosťami projektu sa objavila karta <em>Ganttovo zobrazenie</em>. Zobrazenie umiestni všetky úlohy projektu na časovú os — vodorovný pruh zobrazuje dátum začiatku a konca, s červeným zvýraznením pre oneskorené úlohy.'],
        ],
    ],

    [
        'version' => 'v1.14.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 16.', 'en' => 'May 16, 2026', 'de' => '16. Mai 2026', 'ro' => '16 mai 2026', 'sk' => '16. mája 2026'],
        'items' => [
            ['hu' => '<strong>Német (DE), Román (RO) és Szlovák (SK) nyelvcsomag:</strong> Az admin felület teljes szöveggel bővült három új nyelvvel. A <code>lang/de/</code>, <code>lang/ro/</code> és <code>lang/sk/</code> mappákban az összes modul fordítása elérhető (<code>common</code>, <code>nav</code>, <code>people</code>, <code>events</code>, <code>groups</code>, <code>donations</code>, <code>campaigns</code>, <code>projects</code>, <code>tasks</code>, <code>users</code>, <code>settings</code>, <code>help</code>, <code>changelog</code> stb.).',
             'en'  => '<strong>German (DE), Romanian (RO) and Slovak (SK) language packs:</strong> The admin panel was extended with three new languages with full text coverage. All module translations are available in <code>lang/de/</code>, <code>lang/ro/</code> and <code>lang/sk/</code> folders (<code>common</code>, <code>nav</code>, <code>people</code>, <code>events</code>, <code>groups</code>, <code>donations</code>, <code>campaigns</code>, <code>projects</code>, <code>tasks</code>, <code>users</code>, <code>settings</code>, <code>help</code>, <code>changelog</code>, etc.).', 'de' => '<strong>Deutsche (DE), rumänische (RO) und slowakische (SK) Sprachpakete:</strong> Das Admin-Panel wurde um drei neue Sprachen mit vollständiger Textabdeckung erweitert. Alle Modulübersetzungen sind in den Ordnern <code>lang/de/</code>, <code>lang/ro/</code> und <code>lang/sk/</code> verfügbar (<code>common</code>, <code>nav</code>, <code>people</code>, <code>events</code>, <code>groups</code>, <code>donations</code>, <code>campaigns</code>, <code>projects</code>, <code>tasks</code>, <code>users</code>, <code>settings</code>, <code>help</code>, <code>changelog</code> usw.).', 'ro' => '<strong>Pachete de limbă germană (DE), română (RO) și slovacă (SK):</strong> Panoul de administrare a fost extins cu trei limbi noi cu acoperire completă a textului. Toate traducerile modulelor sunt disponibile în folderele <code>lang/de/</code>, <code>lang/ro/</code> și <code>lang/sk/</code> (<code>common</code>, <code>nav</code>, <code>people</code>, <code>events</code>, <code>groups</code>, <code>donations</code>, <code>campaigns</code>, <code>projects</code>, <code>tasks</code>, <code>users</code>, <code>settings</code>, <code>help</code>, <code>changelog</code> etc.).', 'sk' => '<strong>Jazykové balíky nemčiny (DE), rumunčiny (RO) a slovenčiny (SK):</strong> Admin panel bol rozšírený o tri nové jazyky s úplným pokrytím textu. Všetky preklady modulov sú dostupné v priečinkoch <code>lang/de/</code>, <code>lang/ro/</code> a <code>lang/sk/</code> (<code>common</code>, <code>nav</code>, <code>people</code>, <code>events</code>, <code>groups</code>, <code>donations</code>, <code>campaigns</code>, <code>projects</code>, <code>tasks</code>, <code>users</code>, <code>settings</code>, <code>help</code>, <code>changelog</code> atď.).'],
            ['hu' => '<strong>Nyelvváltó frissítése:</strong> Az oldalsáv HU/EN kapcsolója kiegészült a DE, RO és SK zászlókkal (<code>fi fi-de</code>, <code>fi fi-ro</code>, <code>fi fi-sk</code> SVG ikonok, flag-icons könyvtár). A locale-váltó végpont változatlan: <code>/locale/{locale}</code>.',
             'en'  => '<strong>Language switcher updated:</strong> The HU/EN sidebar switcher was extended with DE, RO and SK flags (<code>fi fi-de</code>, <code>fi fi-ro</code>, <code>fi fi-sk</code> SVG icons, flag-icons library). The locale-switch endpoint is unchanged: <code>/locale/{locale}</code>.', 'de' => '<strong>Sprachumschalter aktualisiert:</strong> Der HU/EN-Sidebar-Umschalter wurde um DE, RO und SK-Flaggen erweitert (<code>fi fi-de</code>, <code>fi fi-ro</code>, <code>fi fi-sk</code> SVG-Symbole, flag-icons-Bibliothek). Der Locale-Wechsel-Endpunkt ist unverändert: <code>/locale/{locale}</code>.', 'ro' => '<strong>Selector de limbă actualizat:</strong> Selectorul din bara laterală HU/EN a fost extins cu steagurile DE, RO și SK (<code>fi fi-de</code>, <code>fi fi-ro</code>, <code>fi fi-sk</code> icoane SVG, biblioteca flag-icons). Punctul final de schimbare a locale-ului este neschimbat: <code>/locale/{locale}</code>.', 'sk' => '<strong>Prepínač jazykov aktualizovaný:</strong> Prepínač HU/EN v bočnom paneli bol rozšírený o vlajky DE, RO a SK (<code>fi fi-de</code>, <code>fi fi-ro</code>, <code>fi fi-sk</code> SVG ikony, knižnica flag-icons). Endpoint prepínania locale je nezmenený: <code>/locale/{locale}</code>.'],
        ],
    ],

    [
        'version' => 'v1.13.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 12.', 'en' => 'May 12, 2026', 'de' => '12. Mai 2026', 'ro' => '12 mai 2026', 'sk' => '12. mája 2026'],
        'items' => [
            ['hu' => '<strong>Esemény bejelentkezés QR-kóddal:</strong> Minden regisztrációhoz egyedi QR-kód generálódik JavaScript alapon (CDN: <code>qrcode.js</code>), amelyet a résztvevő a saját jegy oldalán (<code>/e/ticket/{token}</code>) tekinthet meg. Az admin panel esemény részletoldalán megjelent a <em>Bejelentkezés (ideje)</em> oszlop és egy <em>QR Szkenner</em> gomb. A szkenner oldal (<code>/admin/events/{id}/checkin</code>) kameraalapú QR-beolvasást tesz lehetővé (<code>html5-qrcode</code> CDN, <code>v2.3.8</code>), valós idejű visszajelzéssel (sikeres / már bejelentkezett / ismeretlen token). Manuális token-beviteli mező is elérhető. Az <code>event_registrations</code> táblához <code>checked_in_at</code> (nullable timestamp) oszlop adódott. Statisztikai összesítő sor: összesen / bejelentkezett / még nem érkezett meg.',
             'en'  => '<strong>Event check-in via QR code:</strong> Every registration now has a unique JavaScript-generated QR code (CDN: <code>qrcode.js</code>) accessible on the attendee\'s personal ticket page (<code>/e/ticket/{token}</code>). The admin event detail page now shows a <em>Check-in (time)</em> column and a <em>QR Scanner</em> button. The scanner page (<code>/admin/events/{id}/checkin</code>) supports camera-based QR scanning (<code>html5-qrcode</code> CDN v2.3.8) with real-time feedback (success / already checked in / unknown token). A manual token input field is also available. A <code>checked_in_at</code> (nullable timestamp) column was added to <code>event_registrations</code>. Summary row shows: total / checked in / not yet arrived.', 'de' => '<strong>Veranstaltungs-Check-in per QR-Code:</strong> Jede Registrierung hat nun einen eindeutigen JavaScript-generierten QR-Code (CDN: <code>qrcode.js</code>), der auf der persönlichen Ticket-Seite des Teilnehmers zugänglich ist (<code>/e/ticket/{token}</code>). Die Admin-Ereignisdetailseite zeigt nun eine Spalte <em>Check-in (Zeit)</em> und eine Schaltfläche <em>QR-Scanner</em>. Die Scannerseite (<code>/admin/events/{id}/checkin</code>) unterstützt kamerabasiertes QR-Scannen (<code>html5-qrcode</code> CDN v2.3.8) mit Echtzeit-Feedback (Erfolg / bereits eingecheckt / unbekanntes Token). Ein manuelles Token-Eingabefeld ist ebenfalls verfügbar. Eine Spalte <code>checked_in_at</code> (nullable Timestamp) wurde zu <code>event_registrations</code> hinzugefügt. Zusammenfassungszeile: gesamt / eingecheckt / noch nicht angekommen.', 'ro' => '<strong>Check-in la eveniment prin cod QR:</strong> Fiecare înregistrare are acum un cod QR generat de JavaScript unic (CDN: <code>qrcode.js</code>) accesibil pe pagina de bilet personală a participantului (<code>/e/ticket/{token}</code>). Pagina de detalii a evenimentului din admin afișează acum o coloană <em>Check-in (ora)</em> și un buton <em>Scanner QR</em>. Pagina scanerului (<code>/admin/events/{id}/checkin</code>) suportă scanarea QR bazată pe cameră (<code>html5-qrcode</code> CDN v2.3.8) cu feedback în timp real (succes / deja înregistrat / token necunoscut). Un câmp de introducere manuală a tokenului este de asemenea disponibil. O coloană <code>checked_in_at</code> (timestamp nullable) a fost adăugată la <code>event_registrations</code>. Rândul de rezumat arată: total / înregistrați / nu au sosit încă.', 'sk' => '<strong>Check-in na podujatie cez QR kód:</strong> Každá registrácia má teraz jedinečný JavaScript-generovaný QR kód (CDN: <code>qrcode.js</code>) dostupný na osobnej stránke vstupenky účastníka (<code>/e/ticket/{token}</code>). Stránka s podrobnosťami o podujatí v administrácii teraz zobrazuje stĺpec <em>Check-in (čas)</em> a tlačidlo <em>QR skener</em>. Stránka skenera (<code>/admin/events/{id}/checkin</code>) podporuje skenovanie QR kamerou (<code>html5-qrcode</code> CDN v2.3.8) s real-time spätnou väzbou (úspech / už prihlásený / neznámy token). K dispozícii je aj pole manuálneho zadania tokenu. Stĺpec <code>checked_in_at</code> (nullable timestamp) bol pridaný do <code>event_registrations</code>. Súhrnný riadok zobrazuje: celkom / prihlásení / ešte neprišli.'],
            ['hu' => '<strong>Belépőjegy oldal (publikus):</strong> Sikeres regisztráció után a megerősítő oldalon megjelenik a <em>„Jegyem megtekintése"</em> gomb (token session flash alapján). A jegy oldala tartalmazza az esemény adatait, a résztvevő nevét, kísérők számát, és a QR-kódot, amely a <code>token</code> értékét kódolja. Ha a résztvevő már be van jelentkezve, zöld sáv jelzi a bejelentkezés időpontját. Az oldal nyomtatásra optimalizált.',
             'en'  => '<strong>Personal ticket page (public):</strong> After a successful registration, a <em>"View my ticket"</em> button appears on the confirmation page (using a session flash of the token). The ticket page displays the event details, attendee name, number of guests, and the QR code encoding the <code>token</code> value. If the attendee is already checked in, a green banner shows the check-in timestamp. The page is print-optimised.', 'de' => '<strong>Persönliche Ticket-Seite (öffentlich):</strong> Nach einer erfolgreichen Registrierung erscheint ein Button <em>„Mein Ticket ansehen"</em> auf der Bestätigungsseite (mit einem Session-Flash des Tokens). Die Ticketseite zeigt die Veranstaltungsdetails, den Namen des Teilnehmers, die Anzahl der Gäste und den QR-Code, der den <code>token</code>-Wert kodiert. Wenn der Teilnehmer bereits eingecheckt ist, zeigt ein grünes Banner den Check-in-Zeitstempel. Die Seite ist druckoptimiert.', 'ro' => '<strong>Pagina de bilet personală (publică):</strong> După o înregistrare reușită, un buton <em>„Vizualizați biletul meu"</em> apare pe pagina de confirmare (folosind un flash de sesiune al tokenului). Pagina de bilet afișează detaliile evenimentului, numele participantului, numărul de oaspeți și codul QR care codifică valoarea <code>token</code>. Dacă participantul este deja înregistrat, un banner verde arată timestamp-ul de check-in. Pagina este optimizată pentru tipărire.', 'sk' => '<strong>Osobná stránka vstupenky (verejná):</strong> Po úspešnej registrácii sa na stránke potvrdenia zobrazí tlačidlo <em>„Zobraziť moju vstupenku"</em> (pomocou session flash tokenu). Stránka vstupenky zobrazuje podrobnosti o podujatí, meno účastníka, počet hostí a QR kód kódujúci hodnotu <code>token</code>. Ak je účastník už prihlásený, zelený banner zobrazuje časovú pečiatku check-inu. Stránka je optimalizovaná pre tlač.'],
            ['hu' => '<strong>Várólistakezelés:</strong> Az admin esemény szerkesztő formján megjelent a <em>Várólista engedélyezve</em> kapcsoló. Ha az esemény betelt és a várólista aktív, a publikus regisztrációs oldalon sárga „Feliratkozás a várólistára" űrlap jelenik meg a várakozók aktuális számával. A várólistán szereplők pozíció szerint sorrendben jelennek meg az admin részletoldalon, ahol <em>Előléptet</em> és <em>Töröl</em> gombok is elérhetők. Ha egy adminisztrátor töröl egy megerősített regisztrációt, az első várólistás automatikusan előlép és emailes értesítést kap. Az <code>event_registrations</code> táblához <code>waitlisted</code> (boolean) és <code>waitlist_position</code> (smallint) oszlopok, az <code>events</code> táblához <code>waitlist_enabled</code> (boolean) oszlop adódott.',
             'en'  => '<strong>Waitlist management:</strong> A <em>Waitlist enabled</em> toggle was added to the admin event edit form. When the event is full and the waitlist is active, the public registration page displays a yellow "Join the waiting list" form showing the current number of waiting people. Waitlisted entries appear sorted by position on the admin detail page, with <em>Promote</em> and <em>Remove</em> buttons. When an admin deletes a confirmed registration, the first waitlisted person is automatically promoted and receives a notification email. The <code>event_registrations</code> table gained <code>waitlisted</code> (boolean) and <code>waitlist_position</code> (smallint) columns; the <code>events</code> table gained <code>waitlist_enabled</code> (boolean).'],
            ['hu' => '<strong>Várólistás email értesítők (2 db):</strong> <em>WaitlistConfirmation</em> – sárga stílusú visszaigazoló email, amelyet a várólistára kerülő személy kap, a pozíciószámával. <em>WaitlistPromotion</em> – zöld stílusú „hely felszabadult" értesítő, amelyet az előléptetett személy kap, belépőjegy linkkel. Mindkét email HU/EN kétnyelvű (a küldéskori alkalmazáslocale alapján).',
             'en'  => '<strong>Waitlist email notifications (×2):</strong> <em>WaitlistConfirmation</em> — a yellow-styled confirmation email sent to the person who joined the waitlist, including their position number. <em>WaitlistPromotion</em> — a green-styled "spot available" notification sent to the promoted person, with a ticket link. Both emails are bilingual HU/EN (driven by the application locale at send time).', 'de' => '<strong>Wartelisten-E-Mail-Benachrichtigungen (×2):</strong> <em>WaitlistConfirmation</em> — eine gelb gestaltete Bestätigungs-E-Mail, die an die Person gesendet wird, die sich auf die Warteliste gesetzt hat, einschließlich ihrer Positionsnummer. <em>WaitlistPromotion</em> — eine grün gestaltete „Platz verfügbar"-Benachrichtigung, die an die hochgestufte Person mit einem Ticket-Link gesendet wird. Beide E-Mails sind zweisprachig HU/EN (gesteuert durch das Anwendungslocale zum Sendezeitpunkt).', 'ro' => '<strong>Notificări e-mail pentru lista de așteptare (×2):</strong> <em>WaitlistConfirmation</em> — un e-mail de confirmare cu stil galben trimis persoanei care s-a alăturat listei de așteptare, incluzând numărul poziției sale. <em>WaitlistPromotion</em> — o notificare „loc disponibil" cu stil verde trimisă persoanei promovate, cu un link de bilet. Ambele e-mailuri sunt bilingve HU/EN (determinate de locale-ul aplicației la momentul trimiterii).', 'sk' => '<strong>E-mailové notifikácie pre zoznam čakajúcich (×2):</strong> <em>WaitlistConfirmation</em> — žlto štylizovaný potvrdzovací e-mail zaslaný osobe, ktorá sa pridala do zoznamu čakajúcich, vrátane čísla jej pozície. <em>WaitlistPromotion</em> — zeleno štylizovaná notifikácia „miesto k dispozícii" zaslaná povýšenej osobe s odkazom na vstupenku. Oba e-maily sú dvojjazyčné HU/EN (určené locale aplikácie v čase odoslania).'],
            ['hu' => '<strong>Regisztráció törlése adminból:</strong> Az admin esemény részletoldalon minden regisztrációs sor kapott egy <em>×</em> törlés gombot. Törléskor a rendszer automatikusan ellenőrzi a várólistát, és ha van, az első pozíción lévő várólistás előléptetésre kerül és emailt kap. A várólistán lévők pozíciói automatikusan átrendeződnek.',
             'en'  => '<strong>Registration deletion from admin:</strong> Each registration row on the admin event detail page now has a <em>×</em> delete button. On deletion, the system automatically checks the waitlist and, if present, promotes the first waitlisted entry and sends them a notification email. Waitlist positions are automatically reordered after removal.', 'de' => '<strong>Wartelistenverwaltung:</strong> Ein Umschalter <em>Warteliste aktiviert</em> wurde dem Admin-Veranstaltungsbearbeitungsformular hinzugefügt. Wenn die Veranstaltung voll ist und die Warteliste aktiv ist, zeigt die öffentliche Registrierungsseite ein gelbes „Auf die Warteliste" Formular mit der aktuellen Anzahl wartender Personen. Wartelisteneinträge erscheinen nach Position sortiert auf der Admin-Detailseite mit den Schaltflächen <em>Hochstufen</em> und <em>Entfernen</em>. Wenn ein Admin eine bestätigte Registrierung löscht, wird die erste wartende Person automatisch hochgestuft und erhält eine Benachrichtigungs-E-Mail. Wartelistenpositionen werden nach der Entfernung automatisch neu geordnet.', 'ro' => '<strong>Gestionarea listei de așteptare:</strong> Un comutator <em>Listă de așteptare activată</em> a fost adăugat la formularul de editare a evenimentului din admin. Când evenimentul este plin și lista de așteptare este activă, pagina publică de înregistrare afișează un formular galben „Alăturați-vă listei de așteptare" care arată numărul actual de persoane care așteaptă. Intrările din lista de așteptare apar sortate după poziție pe pagina de detalii admin, cu butoanele <em>Promovare</em> și <em>Eliminare</em>. Când un admin șterge o înregistrare confirmată, prima persoană din lista de așteptare este promovată automat și primește un e-mail de notificare. Pozițiile din lista de așteptare sunt reordonate automat după eliminare.', 'sk' => '<strong>Správa zoznamu čakajúcich:</strong> Do formulára úpravy podujatia v administrácii bol pridaný prepínač <em>Zoznam čakajúcich povolený</em>. Keď je podujatie plné a zoznam čakajúcich je aktívny, verejná stránka registrácie zobrazuje žltý formulár „Pridajte sa do zoznamu čakajúcich" zobrazujúci aktuálny počet čakajúcich. Záznamy v zozname čakajúcich sa zobrazujú zoradené podľa pozície na stránke s podrobnosťami admina s tlačidlami <em>Povýšiť</em> a <em>Odstrániť</em>. Keď admin vymaže potvrdenú registráciu, prvá čakajúca osoba je automaticky povýšená a dostane notifikačný e-mail. Pozície v zozname čakajúcich sú po odstránení automaticky preusporiadané.'],
        ],
    ],

    [
        'version' => 'v1.12.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 10.', 'en' => 'May 10, 2026', 'de' => '10. Mai 2026', 'ro' => '10 mai 2026', 'sk' => '10. mája 2026'],
        'items' => [
            ['hu' => '<strong>Zászló ikonok a nyelvváltóban (sidebar):</strong> A HU / EN nyelvváltó gombok melletti zászlók korábban emoji karakterekként (<code>🇭🇺</code>, <code>🇬🇧</code>) voltak megadva, amelyek Windows rendszeren nem jelennek meg (Chrome / Edge sem rendereli a regionális jelző emoji-kat). Javítás: a <a href="https://flagicons.lipis.dev" target="_blank">flag-icons</a> SVG könyvtár (CDN, v7.2.3) betöltésre kerül, és az emoji helyett <code>&lt;span class="fi fi-hu"&gt;</code> / <code>&lt;span class="fi fi-gb"&gt;</code> elemek kerülnek használatba. Az ikonok most minden platformon és böngészőben egységesen jelennek meg.',
             'en'  => '<strong>Flag icons in the language switcher (sidebar):</strong> The flags next to the HU / EN language switcher buttons were previously emoji characters (<code>🇭🇺</code>, <code>🇬🇧</code>), which do not render on Windows (Chrome / Edge does not support regional indicator emoji sequences). Fix: the <a href="https://flagicons.lipis.dev" target="_blank">flag-icons</a> SVG library (CDN, v7.2.3) is now loaded and <code>&lt;span class="fi fi-hu"&gt;</code> / <code>&lt;span class="fi fi-gb"&gt;</code> elements replace the emoji. Flags now render consistently across all platforms and browsers.', 'de' => '<strong>Flaggen-Icons im Sprachumschalter (Seitenleiste):</strong> Die Flaggen neben den HU/EN-Sprachumschalter-Schaltflächen waren zuvor Emoji-Zeichen (<code>🇭🇺</code>, <code>🇬🇧</code>), die unter Windows nicht gerendert werden (Chrome/Edge unterstützt keine regionalen Indikator-Emoji-Sequenzen). Lösung: Die SVG-Bibliothek <a href="https://flagicons.lipis.dev" target="_blank">flag-icons</a> (CDN, v7.2.3) wird nun geladen und <code>&lt;span class="fi fi-hu"&gt;</code> / <code>&lt;span class="fi fi-gb"&gt;</code>-Elemente ersetzen die Emoji. Flaggen werden nun auf allen Plattformen und Browsern einheitlich gerendert.', 'ro' => '<strong>Icoane de steag în selectorul de limbă (bara laterală):</strong> Steagurile de lângă butoanele selectoare de limbă HU/EN erau anterior caractere emoji (<code>🇭🇺</code>, <code>🇬🇧</code>), care nu se randează pe Windows (Chrome/Edge nu suportă secvențele de emoji indicator regional). Soluție: biblioteca SVG <a href="https://flagicons.lipis.dev" target="_blank">flag-icons</a> (CDN, v7.2.3) este acum încărcată și elementele <code>&lt;span class="fi fi-hu"&gt;</code> / <code>&lt;span class="fi fi-gb"&gt;</code> înlocuiesc emoji-urile. Steagurile se randează acum consistent pe toate platformele și browserele.', 'sk' => '<strong>Ikony vlajok v prepínači jazykov (bočný panel):</strong> Vlajky vedľa tlačidiel prepínača jazykov HU/EN boli predtým znaky emoji (<code>🇭🇺</code>, <code>🇬🇧</code>), ktoré sa na Windows nevykresľujú (Chrome/Edge nepodporuje sekvencie emoji regionálneho indikátora). Oprava: SVG knižnica <a href="https://flagicons.lipis.dev" target="_blank">flag-icons</a> (CDN, v7.2.3) je teraz načítaná a elementy <code>&lt;span class="fi fi-hu"&gt;</code> / <code>&lt;span class="fi fi-gb"&gt;</code> nahrádzajú emoji. Vlajky sa teraz vykresľujú konzistentne na všetkých platformách a prehliadačoch.'],
            ['hu' => '<strong>README — teljes funkciólista ✅ / 🔲 jelölésekkel:</strong> A projekt README-je gyökeresen átdolgozásra került. Az összes meglévő funkció ✅ jelöléssel, az összes tervezett fejlesztés 🔲 jelöléssel szerepel, modulonként csoportosítva: Kapcsolatok (CRM), Csoportok, Események, Email kampányok, Adományok, Projektek & Feladatok, Dashboard, Felhasználók & Szerepkörök, Link gyűjtemény, Beállítások, Súgó, Többnyelvűség, Integrációk & API, Advanced / Enterprise. Így GitHub-on bármely érdeklődő egyetlen pillantással átláthatja, mi elérhető és mi van tervezőasztalon.',
             'en'  => '<strong>README — comprehensive feature list with ✅ / 🔲 markers:</strong> The project README was comprehensively rewritten. All implemented features are marked ✅ and all planned features are marked 🔲, grouped by module: Contacts (CRM), Groups, Events, Email Campaigns, Donations, Projects & Tasks, Dashboard, Users & Roles, Link Collection, Settings, Help & Documentation, Multi-language, Integrations & API, Advanced / Enterprise. This gives anyone visiting the GitHub repo an instant overview of what is available and what is on the roadmap.', 'de' => '<strong>README — umfassende Funktionsliste mit ✅ / 🔲 Markierungen:</strong> Das Projekt-README wurde umfassend neu geschrieben. Alle implementierten Funktionen sind mit ✅ markiert und alle geplanten Funktionen mit 🔲, gruppiert nach Modul: Kontakte (CRM), Gruppen, Veranstaltungen, E-Mail-Kampagnen, Spenden, Projekte & Aufgaben, Dashboard, Benutzer & Rollen, Link-Sammlung, Einstellungen, Hilfe & Dokumentation, Mehrsprachigkeit, Integrationen & API, Erweitert / Enterprise. Dies gibt jedem, der das GitHub-Repo besucht, einen sofortigen Überblick über das Verfügbare und die Roadmap.', 'ro' => '<strong>README — lista completă de funcționalități cu marcaje ✅ / 🔲:</strong> README-ul proiectului a fost rescris complet. Toate funcționalitățile implementate sunt marcate ✅ și toate funcționalitățile planificate sunt marcate 🔲, grupate pe module: Contacte (CRM), Grupuri, Evenimente, Campanii de e-mail, Donații, Proiecte & Sarcini, Dashboard, Utilizatori & Roluri, Colecție de linkuri, Setări, Ajutor & Documentație, Multilingv, Integrări & API, Avansat / Enterprise. Aceasta oferă oricui vizitează repo-ul GitHub o prezentare instantanee a ceea ce este disponibil și ce este pe foaia de parcurs.', 'sk' => '<strong>README — komplexný zoznam funkcií s označeniami ✅ / 🔲:</strong> README projektu bolo komplexne prepísané. Všetky implementované funkcie sú označené ✅ a všetky plánované funkcie sú označené 🔲, zoskupené podľa modulu: Kontakty (CRM), Skupiny, Udalosti, E-mailové kampane, Dary, Projekty a úlohy, Dashboard, Používatelia a roly, Zbierka odkazov, Nastavenia, Pomoc a dokumentácia, Viacjazyčnosť, Integrácie a API, Pokročilé / Enterprise. To dáva každému, kto navštívi GitHub repo, okamžitý prehľad o tom, čo je k dispozícii a čo je na pláne.'],
            ['hu' => '<strong>Open Core tábla és Advanced / Enterprise szekció szinkronizálása:</strong> A README Open Core összehasonlító táblája és a Features lista Advanced / Enterprise szekciója összhangba hozásra került. A Kétfaktoros hitelesítés (TOTP) és a REST API for mobile clients tételek kizárólag az Enterprise szekcióba kerültek (korábban a Felhasználók & Szerepkörök, ill. Integrációk & API szekciókban is szerepeltek). Az Open Core tábla bővült: Dokumentumtároló, Kérdőív & űrlapkészítő, Petíció / aláírásgyűjtés, Önkéntes órakövetés sorokkal.',
             'en'  => '<strong>Open Core table and Advanced / Enterprise section synchronised:</strong> The README Open Core comparison table and the Advanced / Enterprise section in the Features list have been brought into full alignment. Two-factor authentication (TOTP) and REST API for mobile clients are now exclusively listed under the Enterprise section (previously they also appeared under Users & Roles and Integrations & API). The Open Core table was expanded with new rows: Document storage, Survey & form builder, Petition / signature collection, Volunteer hours tracking.', 'de' => '<strong>Open Core-Tabelle und Abschnitt Erweitert / Enterprise synchronisiert:</strong> Die Open Core-Vergleichstabelle und der Abschnitt Erweitert / Enterprise in der Funktionsliste wurden vollständig angeglichen. Zwei-Faktor-Authentifizierung (TOTP) und REST API für mobile Clients sind nun ausschließlich im Enterprise-Abschnitt aufgeführt. Die Open Core-Tabelle wurde mit neuen Zeilen erweitert: Dokumentenspeicher, Umfrage- & Formular-Builder, Petition / Unterschriftensammlung, Ehrenamtliche Zeiterfassung.', 'ro' => '<strong>Tabelul Open Core și secțiunea Avansat / Enterprise sincronizate:</strong> Tabelul de comparație Open Core și secțiunea Avansat / Enterprise din lista de funcționalități au fost aduse în deplină aliniere. Autentificarea cu doi factori (TOTP) și REST API pentru clienți mobili sunt acum enumerate exclusiv în secțiunea Enterprise. Tabelul Open Core a fost extins cu rânduri noi: Stocare documente, Constructor de sondaje & formulare, Petiție / colectare de semnături, Urmărirea orelor de voluntariat.', 'sk' => '<strong>Tabuľka Open Core a sekcia Pokročilé / Enterprise synchronizované:</strong> Porovnávacia tabuľka Open Core a sekcia Pokročilé / Enterprise v zozname funkcií boli uvedené do úplného súladu. Dvojfaktorová autentifikácia (TOTP) a REST API pre mobilných klientov sú teraz uvedené výhradne v sekcii Enterprise. Tabuľka Open Core bola rozšírená o nové riadky: Úložisko dokumentov, Tvorca prieskumov & formulárov, Petícia / zbierka podpisov, Sledovanie dobrovoľníckych hodín.'],
            ['hu' => '<strong>Súgó gomb áthelyezése a gyorslinkek sávba:</strong> A Főoldal jobb felső sarkából eltávolításra került a Súgó gomb. A gyorslinkek sávba (kék topbar) kerülve az Infografikonok mellé, most bármely oldalról elérhetővé vált anélkül, hogy el kellene navigálni a Főoldalra. A bal oldali menüben a „Súgó kezelése" felirat „Súgó"-ra egyszerűsödött.',
             'en'  => '<strong>Help button moved to quick links bar:</strong> The Help button was removed from the top-right corner of the Dashboard and placed in the quick links bar (blue topbar) next to Infographics — now accessible from any page without navigating back to the Dashboard. The left sidebar label "Manage Help" was simplified to "Help".', 'de' => '<strong>Hilfe-Schaltfläche in die Schnelllinks-Leiste verschoben:</strong> Die Hilfe-Schaltfläche wurde aus der oberen rechten Ecke des Dashboards entfernt und in der Schnelllinks-Leiste (blauer Topbar) neben Infografiken platziert — nun von jeder Seite aus zugänglich, ohne zum Dashboard zurückzunavigieren. Der linke Seitenleistenname „Hilfe verwalten" wurde zu „Hilfe" vereinfacht.', 'ro' => '<strong>Butonul Ajutor mutat în bara de linkuri rapide:</strong> Butonul Ajutor a fost eliminat din colțul din dreapta sus al Dashboard-ului și plasat în bara de linkuri rapide (bara albastră topbar) lângă Infografice — acum accesibil de pe orice pagină fără a naviga înapoi la Dashboard. Eticheta barei laterale stângi „Gestionare Ajutor" a fost simplificată la „Ajutor".', 'sk' => '<strong>Tlačidlo Pomocník presunuté do lišty rýchlych odkazov:</strong> Tlačidlo Pomocník bolo odstránené z pravého horného rohu dashboardu a umiestnené do lišty rýchlych odkazov (modrý topbar) vedľa Infografík — teraz dostupné z ľubovoľnej stránky bez navigácie späť na Dashboard. Označenie ľavého bočného panela „Správa pomocníka" bolo zjednodušené na „Pomocník".'],
            ['hu' => '<strong>CSV / Excel import &amp; export (Kapcsolatok):</strong> A <code>/admin/people</code> oldalon az összes kapcsolat exportálható CSV (UTF-8 BOM, pontosvesszős elválasztó) vagy Excel (XLSX, félkövér fejléc) formátumban. Import: CSV és XLSX fájlból, oszlopnév-alapú leképzéssel, meglévő emailcímek kihagyásával. A <code>phpoffice/phpspreadsheet</code> könyvtár kezeli az XLSX fájlokat.',
             'en'  => '<strong>CSV / Excel import &amp; export (Contacts):</strong> On the <code>/admin/people</code> page, all contacts can be exported as CSV (UTF-8 BOM, semicolon separator) or Excel (XLSX, bold header). Import: from CSV or XLSX file with column-name-based mapping, skipping existing email addresses. The <code>phpoffice/phpspreadsheet</code> library handles XLSX files.', 'de' => '<strong>CSV / Excel Import &amp; Export (Kontakte):</strong> Auf der Seite <code>/admin/people</code> können alle Kontakte als CSV (UTF-8 BOM, durch Semikolon getrennt) oder Excel (XLSX, fetter Header) exportiert werden. Import: aus CSV- oder XLSX-Dateien mit spaltennamensbasierter Zuordnung, Überspringen vorhandener E-Mail-Adressen. Die Bibliothek <code>phpoffice/phpspreadsheet</code> verarbeitet XLSX-Dateien.', 'ro' => '<strong>Import &amp; Export CSV / Excel (Contacte):</strong> Pe pagina <code>/admin/people</code>, toate contactele pot fi exportate ca CSV (UTF-8 BOM, separator punct și virgulă) sau Excel (XLSX, antet îngroșat). Import: din fișier CSV sau XLSX cu mapare bazată pe numele coloanei, sărindu-se adresele de e-mail existente. Biblioteca <code>phpoffice/phpspreadsheet</code> gestionează fișierele XLSX.', 'sk' => '<strong>Import &amp; export CSV / Excel (Kontakty):</strong> Na stránke <code>/admin/people</code> je možné exportovať všetky kontakty ako CSV (UTF-8 BOM, oddelené bodkočiarkou) alebo Excel (XLSX, tučná hlavička). Import: zo súboru CSV alebo XLSX s mapovaním na základe názvov stĺpcov, preskakovaním existujúcich e-mailových adries. Knižnica <code>phpoffice/phpspreadsheet</code> spracúva súbory XLSX.'],
            ['hu' => '<strong>Speciális szűrők és mentett keresések (Kapcsolatok):</strong> Kibővített szűrőpanel: keresés, státusz (több is), város, forrás, hírlevél, csoport, regisztrációs dátumtartomány, lead fázis és minimum pontszám. A szűrőkombinációk névvel elmenthetők és egy kattintással visszatölthetők — felhasználónkénti szűrő-előbeállítások, <code>people_saved_filters</code> tábla.',
             'en'  => '<strong>Advanced filters and saved searches (Contacts):</strong> Expanded filter panel: text search, status (multi-select chips), city, source, newsletter subscription, group, registration date range, lead stage and minimum score. Filter combinations can be saved by name and reloaded in one click — per-user filter presets stored in the <code>people_saved_filters</code> table.', 'de' => '<strong>Erweiterte Filter und gespeicherte Suchen (Kontakte):</strong> Erweitertes Filterpanel: Textsuche, Status (Mehrfachauswahl-Chips), Stadt, Quelle, Newsletter-Abonnement, Gruppe, Registrierungsdatumsbereich, Lead-Phase und Mindestpunktzahl. Filterkombinationen können mit Namen gespeichert und mit einem Klick neu geladen werden — benutzerspezifische Filter-Voreinstellungen in der Tabelle <code>people_saved_filters</code>.', 'ro' => '<strong>Filtre avansate și căutări salvate (Contacte):</strong> Panel de filtre extins: căutare text, status (chips cu selecție multiplă), oraș, sursă, abonament la newsletter, grup, interval de date de înregistrare, etapă de lead și scor minim. Combinațiile de filtre pot fi salvate după nume și reîncărcate cu un singur clic — presetări de filtre per utilizator stocate în tabelul <code>people_saved_filters</code>.', 'sk' => '<strong>Pokročilé filtre a uložené vyhľadávania (Kontakty):</strong> Rozšírený panel filtrov: textové vyhľadávanie, stav (multi-výberové čipy), mesto, zdroj, odber newslettera, skupina, rozsah dátumov registrácie, fáza leadu a minimálne skóre. Kombinácie filtrov je možné uložiť podľa názvu a jedným kliknutím ich znova načítať — predvoľby filtrov pre každého používateľa uložené v tabuľke <code>people_saved_filters</code>.'],
            ['hu' => '<strong>Duplikátum-keresés és kapcsolat-összevonás:</strong> Új <code>/admin/people/duplicates</code> oldal, amely email, telefonszám és teljes név (kis-/nagybetű-független) alapján azonosítja a valószínű duplikátumokat. A párokat kártyán jeleníti meg az egyezés okával (email/telefon/név badge). Összevonáskor az üres mezők automatikusan töltődnek fel a másik profilból, az adományok, esemény RSVP-k és csoporttagságok átkerülnek, a duplikátum soft-delete-elve lesz.',
             'en'  => '<strong>Duplicate detection and contact merge:</strong> New <code>/admin/people/duplicates</code> page that identifies probable duplicates by email, phone and full name (case-insensitive). Pairs are shown on cards with the match reason (email / phone / name badge). On merge, empty fields are auto-filled from the other profile, donations, event RSVPs and group memberships are transferred, and the duplicate is soft-deleted.', 'de' => '<strong>Duplikatserkennung und Kontaktzusammenführung:</strong> Neue Seite <code>/admin/people/duplicates</code>, die wahrscheinliche Duplikate nach E-Mail, Telefon und vollständigem Namen (Groß-/Kleinschreibung unempfindlich) identifiziert. Paare werden auf Karten mit dem Übereinstimmungsgrund (E-Mail / Telefon / Name-Badge) angezeigt. Bei der Zusammenführung werden leere Felder automatisch aus dem anderen Profil ausgefüllt, Spenden, Veranstaltungs-RSVPs und Gruppenmitgliedschaften werden übertragen, und das Duplikat wird soft-gelöscht.', 'ro' => '<strong>Detectarea duplicatelor și fuzionarea contactelor:</strong> Noua pagină <code>/admin/people/duplicates</code> care identifică duplicatele probabile după e-mail, telefon și numele complet (insensibil la majuscule/minuscule). Perechile sunt afișate pe carduri cu motivul potrivirii (badge e-mail / telefon / nume). La fuzionare, câmpurile goale sunt completate automat din celălalt profil, donațiile, RSVP-urile la evenimente și apartenența la grupuri sunt transferate, iar duplicatul este șters soft.', 'sk' => '<strong>Detekcia duplikátov a zlučovanie kontaktov:</strong> Nová stránka <code>/admin/people/duplicates</code>, ktorá identifikuje pravdepodobné duplikáty podľa e-mailu, telefónu a celého mena (bez rozlišovania veľkých/malých písmen). Páry sú zobrazené na kartách s dôvodom zhody (badge e-mail / telefón / meno). Pri zlučovaní sa prázdne polia automaticky vyplnia z druhého profilu, dary, RSVP udalostí a členstvá v skupinách sú prenesené a duplikát je soft-vymazaný.'],
            ['hu' => '<strong>Kapcsolatonkénti aktivitás napló:</strong> Minden kapcsolathoz interakciótörténet rögzíthető: Telefonhívás, Email, Megbeszélés, Feljegyzés, Feladat, SMS, Egyéb — időponttal, megjegyzéssel és rögzítő felhasználóval. A <code>contact_activities</code> tábla tárolja az adatokat. A kapcsolat részletoldalán szín-kódolt, ikonos vertikális timeline formában jelenik meg.',
             'en'  => '<strong>Per-contact activity log:</strong> Interaction history can be recorded for every contact: Phone call, Email, Meeting, Note, Task, SMS, Other — with timestamp, notes and the recording user. Stored in the <code>contact_activities</code> table. Displayed as a colour-coded, icon-based vertical timeline on the contact detail page.', 'de' => '<strong>Kontaktbezogenes Aktivitätsprotokoll:</strong> Interaktionshistorie kann für jeden Kontakt aufgezeichnet werden: Telefonanruf, E-Mail, Besprechung, Notiz, Aufgabe, SMS, Sonstiges — mit Zeitstempel, Notizen und dem aufzeichnenden Benutzer. Gespeichert in der Tabelle <code>contact_activities</code>. Wird als farbcodierte, ikonenbasierte vertikale Zeitleiste auf der Kontaktdetailseite angezeigt.', 'ro' => '<strong>Jurnal de activitate per contact:</strong> Istoricul interacțiunilor poate fi înregistrat pentru fiecare contact: Apel telefonic, E-mail, Întâlnire, Notă, Sarcină, SMS, Altele — cu timestamp, note și utilizatorul care le-a înregistrat. Stocat în tabelul <code>contact_activities</code>. Afișat ca o cronologie verticală codificată prin culori, bazată pe icoane, pe pagina de detalii a contactului.', 'sk' => '<strong>Denník aktivity na kontakt:</strong> Pre každý kontakt je možné zaznamenať históriu interakcií: Telefonický hovor, E-mail, Stretnutie, Poznámka, Úloha, SMS, Iné — s časovou pečiatkou, poznámkami a zaznamenávajúcim používateľom. Uložené v tabuľke <code>contact_activities</code>. Zobrazené ako farebne kódovaná, ikona-založená vertikálna časová os na stránke s podrobnosťami kontaktu.'],
            ['hu' => '<strong>Kapcsolatfelvétel / érdeklődőértékelés (Lead scoring):</strong> Minden kapcsolathoz beállítható 6 fázisú értékesítési pipeline (Új érdeklődő → Kapcsolatba lépve → Minősített → Ajánlat küldve → Megnyert → Elveszett) és 1–5 csillagos érdeklődési pontszám. A <code>people</code> tábla bővül <code>lead_stage</code> és <code>lead_score</code> oszlopokkal. A listában Értékelés oszlop jelenik meg; fázis és minimum pontszám alapján szűrhető.',
             'en'  => '<strong>Contact intake / lead scoring:</strong> Each contact can be assigned a 6-stage sales pipeline (New Lead → Contacted → Qualified → Proposal Sent → Converted → Lost) and a 1–5 star interest score. The <code>people</code> table gains <code>lead_stage</code> and <code>lead_score</code> columns. An Evaluation column appears in the contacts list; filterable by stage and minimum score.', 'de' => '<strong>Kontaktaufnahme / Lead-Scoring:</strong> Jedem Kontakt kann eine 6-stufige Vertriebspipeline zugewiesen werden (Neuer Lead → Kontaktiert → Qualifiziert → Angebot gesendet → Konvertiert → Verloren) und ein 1–5-Sterne-Interessenpunktzahl. Die Tabelle <code>people</code> erhält die Spalten <code>lead_stage</code> und <code>lead_score</code>. In der Kontaktliste erscheint eine Bewertungsspalte; filterbar nach Phase und Mindestpunktzahl.', 'ro' => '<strong>Captare contacte / Lead scoring:</strong> Fiecărui contact i se poate atribui un pipeline de vânzări cu 6 etape (Lead nou → Contactat → Calificat → Propunere trimisă → Convertit → Pierdut) și un scor de interes de 1–5 stele. Tabelul <code>people</code> câștigă coloanele <code>lead_stage</code> și <code>lead_score</code>. O coloană de Evaluare apare în lista de contacte; filtrabilă după etapă și scor minim.', 'sk' => '<strong>Príjem kontaktov / Lead scoring:</strong> Každému kontaktu je možné priradiť 6-fázový predajný pipeline (Nový lead → Kontaktovaný → Kvalifikovaný → Zaslaný návrh → Konvertovaný → Stratený) a skóre záujmu 1–5 hviezdičiek. Tabuľka <code>people</code> získa stĺpce <code>lead_stage</code> a <code>lead_score</code>. V zozname kontaktov sa zobrazí stĺpec Hodnotenie; filtrovateľný podľa fázy a minimálneho skóre.'],
        ],
    ],

    [
        'version' => 'v1.11.0',
        'badge'   => [
            'text'  => ['hu' => 'Hibajavítás', 'en' => 'Bug Fix', 'de' => 'Fehlerbehebung', 'ro' => 'Remediere erori', 'sk' => 'Oprava chyby'],
            'style' => 'background:rgba(240,101,72,0.1);color:#f06548;',
        ],
        'date' => ['hu' => '2026. május 8.', 'en' => 'May 8, 2026', 'de' => '8. Mai 2026', 'ro' => '8 mai 2026', 'sk' => '8. mája 2026'],
        'items' => [
            ['hu' => '<strong>Email kampány modul — hibajavítás csomag (Pro):</strong> Az email kampány küldési funkció több kritikus hibája javításra került: a <code>is_subscribed</code> mező helyes használata (volt: <code>newsletter</code>), a <code>full_name</code> accessor használata (nem létező <code>name</code> oszlop helyett), az üres <code>\$e</code> catch változó elhárítása, valamint az utolsó <code>$campaign->update()</code> hívás köré helyezett try/catch védelem <em>failed</em> státusz esetére.',
             'en' => '<strong>Email campaign module — bug fix bundle (Pro):</strong> Several critical bugs in the email campaign send flow were fixed: correct use of the <code>is_subscribed</code> field (was: <code>newsletter</code>), use of the <code>full_name</code> accessor (instead of non-existent <code>name</code> column), removal of unused <code>$e</code> catch variable, and a try/catch wrapper around the final <code>$campaign->update()</code> call for the <em>failed</em> status case.', 'de' => '<strong>E-Mail-Kampagnenmodul — Fehlerbehebungspaket (Pro):</strong> Mehrere kritische Fehler im E-Mail-Kampagnen-Sendeablauf wurden behoben: korrekte Verwendung des Feldes <code>is_subscribed</code> (war: <code>newsletter</code>), Verwendung des <code>full_name</code>-Accessors (statt der nicht existierenden <code>name</code>-Spalte), Entfernung der ungenutzten <code>$e</code>-catch-Variable und ein try/catch-Wrapper um den abschließenden <code>$campaign->update()</code>-Aufruf für den <em>failed</em>-Status.', 'ro' => '<strong>Modul campanii e-mail — pachet de remediere erori (Pro):</strong> Mai multe erori critice în fluxul de trimitere a campaniei de e-mail au fost remediate: utilizarea corectă a câmpului <code>is_subscribed</code> (era: <code>newsletter</code>), utilizarea accessorului <code>full_name</code> (în locul coloanei inexistente <code>name</code>), eliminarea variabilei catch neutilizate <code>$e</code> și un wrapper try/catch în jurul apelului final <code>$campaign->update()</code> pentru cazul de stare <em>failed</em>.', 'sk' => '<strong>Modul e-mailových kampaní — balík opráv chýb (Pro):</strong> Niekoľko kritických chýb v toku odosielania e-mailových kampaní bolo opravených: správne použitie poľa <code>is_subscribed</code> (bolo: <code>newsletter</code>), použitie accessora <code>full_name</code> (namiesto neexistujúceho stĺpca <code>name</code>), odstránenie nepoužívanej catch premennej <code>$e</code> a wrapper try/catch okolo záverečného volania <code>$campaign->update()</code> pre prípad stavu <em>failed</em>.'],
            ['hu' => '<strong>Kampány modal javítás:</strong> A kampány létrehozás és szerkesztés modaljain helytelen CSS osztály (<code>nf-modal-backdrop</code>) volt megadva, ami miatt a modalisablonok nem nyíltak meg. Javítva: <code>nf-overlay</code>.',
             'en' => '<strong>Campaign modal fix:</strong> The campaign create and edit modals had an incorrect CSS class (<code>nf-modal-backdrop</code>) that prevented them from opening. Fixed to <code>nf-overlay</code>.', 'de' => '<strong>Kampagnen-Modal-Korrektur:</strong> Die Kampagnenerstellungs- und -bearbeitungsmodals hatten eine falsche CSS-Klasse (<code>nf-modal-backdrop</code>), die das Öffnen verhinderte. Korrigiert zu <code>nf-overlay</code>.', 'ro' => '<strong>Remediere modal campanie:</strong> Modalele de creare și editare a campaniei aveau o clasă CSS incorectă (<code>nf-modal-backdrop</code>) care împiedica deschiderea lor. Corectat la <code>nf-overlay</code>.', 'sk' => '<strong>Oprava modálneho okna kampane:</strong> Modálne okná vytvorenia a úpravy kampane mali nesprávnu CSS triedu (<code>nf-modal-backdrop</code>), ktorá bránila ich otvoreniu. Opravené na <code>nf-overlay</code>.'],
            ['hu' => '<strong>Feliratkozók száma piszkozat kampányoknál:</strong> A kampány lista Fogadók oszlopa piszkozat állapotú kampányoknál korábban „—” jelet mutatott. Mostantól a valós hírlevél feliratkozók száma jelenik meg.',
             'en' => '<strong>Subscriber count for draft campaigns:</strong> The Recipients column in the campaign list previously showed "—" for draft campaigns. It now correctly displays the actual newsletter subscriber count.', 'de' => '<strong>Abonnentenanzahl für Entwurfskampagnen:</strong> Die Spalte Empfänger in der Kampagnenliste zeigte für Entwurfskampagnen zuvor „—". Sie zeigt nun korrekt die tatsächliche Anzahl der Newsletter-Abonnenten an.', 'ro' => '<strong>Numărul de abonați pentru campaniile schiță:</strong> Coloana Destinatari din lista de campanii afișa anterior „—" pentru campaniile schiță. Acum afișează corect numărul real de abonați la newsletter.', 'sk' => '<strong>Počet odberateľov pre konceptové kampane:</strong> Stĺpec Príjemcovia v zozname kampaní predtým zobrazoval „—" pre konceptové kampane. Teraz správne zobrazuje skutočný počet odberateľov newslettera.'],
            ['hu' => '<strong>Feladó cím javítása (<code>CampaignMail</code>):</strong> Az emailek küldésékor a feladó cím helytelenül, csonkítva jelent meg (pl. <code>admin@</code> domain nélkül). A <code>CampaignMail::envelope()</code> most explicitén a kampányban tárolt <code>from_email</code> és <code>from_name</code> értékeket használja (<code>Illuminate\\Mail\\Mailables\\Address</code> segítségével), config fallbackkel.',
             'en' => '<strong>Sender address fix (<code>CampaignMail</code>):</strong> When sending emails, the sender address appeared incorrectly truncated (e.g. <code>admin@</code> without domain). <code>CampaignMail::envelope()</code> now explicitly uses the campaign\'s stored <code>from_email</code> and <code>from_name</code> values (via <code>Illuminate\\Mail\\Mailables\\Address</code>), with config fallback.', 'de' => '<strong>Absenderadressen-Korrektur (<code>CampaignMail</code>):</strong> Beim Senden von E-Mails erschien die Absenderadresse falsch abgeschnitten (z.B. <code>admin@</code> ohne Domain). <code>CampaignMail::envelope()</code> verwendet nun explizit die in der Kampagne gespeicherten Werte <code>from_email</code> und <code>from_name</code> (über <code>Illuminate\\Mail\\Mailables\\Address</code>), mit Konfigurations-Fallback.', 'ro' => '<strong>Remediere adresă expeditor (<code>CampaignMail</code>):</strong> La trimiterea e-mailurilor, adresa expeditorului apărea incorect trunchiată (de ex. <code>admin@</code> fără domeniu). <code>CampaignMail::envelope()</code> utilizează acum explicit valorile <code>from_email</code> și <code>from_name</code> stocate în campanie (prin <code>Illuminate\\Mail\\Mailables\\Address</code>), cu fallback din configurație.', 'sk' => '<strong>Oprava adresy odosielateľa (<code>CampaignMail</code>):</strong> Pri odosielaní e-mailov sa adresa odosielateľa zobrazovala nesprávne skrátená (napr. <code>admin@</code> bez domény). <code>CampaignMail::envelope()</code> teraz explicitne používa hodnoty <code>from_email</code> a <code>from_name</code> uložené v kampani (cez <code>Illuminate\\Mail\\Mailables\\Address</code>), s fallbackom z konfigurácie.'],
            ['hu' => '<strong><code>failed_count</code> oszlop és ENUM bővítés (migráció):</strong> Két új migráció: az <code>email_campaigns</code> táblához hozzáadásra kerültek a <code>failed_count</code> (unsignedInteger, default 0) oszlop, valamint a <em>failed</em> státusz értéke az ENUM mezőhöz — raw <code>ALTER TABLE</code> SQL-lel, mivel a MySQL ENUM módosítás nem lehetséges Laravelblueprint-tel.',
             'en' => '<strong><code>failed_count</code> column and ENUM extension (migration):</strong> Two new migrations: the <code>failed_count</code> (unsignedInteger, default 0) column and the <em>failed</em> status value were added to the <code>email_campaigns</code> table — using raw <code>ALTER TABLE</code> SQL, as MySQL ENUM modification is not possible with Laravel Blueprint.', 'de' => '<strong><code>failed_count</code>-Spalte und ENUM-Erweiterung (Migration):</strong> Zwei neue Migrationen: die Spalte <code>failed_count</code> (unsignedInteger, Standard 0) und der Statuswert <em>failed</em> wurden zur Tabelle <code>email_campaigns</code> hinzugefügt — mit rohem <code>ALTER TABLE</code>-SQL, da die MySQL-ENUM-Modifikation mit Laravel Blueprint nicht möglich ist.', 'ro' => '<strong>Coloana <code>failed_count</code> și extensia ENUM (migrare):</strong> Două noi migrări: coloana <code>failed_count</code> (unsignedInteger, implicit 0) și valoarea de stare <em>failed</em> au fost adăugate la tabelul <code>email_campaigns</code> — folosind SQL <code>ALTER TABLE</code> brut, deoarece modificarea MySQL ENUM nu este posibilă cu Laravel Blueprint.', 'sk' => '<strong>Stĺpec <code>failed_count</code> a rozšírenie ENUM (migrácia):</strong> Dve nové migrácie: stĺpec <code>failed_count</code> (unsignedInteger, predvolene 0) a hodnota stavu <em>failed</em> boli pridané do tabuľky <code>email_campaigns</code> — pomocou surového SQL <code>ALTER TABLE</code>, keďže modifikácia MySQL ENUM nie je možná s Laravel Blueprint.'],
            ['hu' => '<strong>Duplikált migráció eltávolítása (Forge deployment fix):</strong> A <code>2026_05_08_190846_create_email_campaigns_table.php</code> migráció — amely lokálisan manuálisan volt hozzáadva az adatbázishoz — eltávolításra került a git repóból. A Forge szerveren ez a duplikált migráció <em>„table already exists"</em> hibával akadályozta a deployment-et.',
             'en' => '<strong>Duplicate migration removed (Forge deployment fix):</strong> The <code>2026_05_08_190846_create_email_campaigns_table.php</code> migration — which was manually added to the database locally — was removed from the git repository. On the Forge server, this duplicate migration was blocking deployment with a <em>"table already exists"</em> error.', 'de' => '<strong>Doppelte Migration entfernt (Forge-Deployment-Fix):</strong> Die Migration <code>2026_05_08_190846_create_email_campaigns_table.php</code> — die lokal manuell zur Datenbank hinzugefügt wurde — wurde aus dem Git-Repository entfernt. Auf dem Forge-Server blockierte diese doppelte Migration das Deployment mit einem <em>„Tabelle existiert bereits"</em>-Fehler.', 'ro' => '<strong>Migrare duplicată eliminată (remediere deployment Forge):</strong> Migrarea <code>2026_05_08_190846_create_email_campaigns_table.php</code> — care a fost adăugată manual la baza de date local — a fost eliminată din repository-ul git. Pe serverul Forge, această migrare duplicată bloca deployment-ul cu o eroare <em>„tabelul există deja"</em>.', 'sk' => '<strong>Odstránená duplicitná migrácia (oprava nasadenia Forge):</strong> Migrácia <code>2026_05_08_190846_create_email_campaigns_table.php</code> — ktorá bola lokálne manuálne pridaná do databázy — bola odstránená z git repozitára. Na serveri Forge táto duplicitná migrácia blokovala nasadenie s chybou <em>„tabuľka už existuje"</em>.'],
            ['hu' => '<strong>Dashboard TypeError javítás (Windows / HU locale):</strong> A <code>/dashboard</code> oldal <code>TypeError: htmlspecialchars() array given</code> hibával omlott össze. Gyökérok: Windows fájlrendszer nem különbözteti meg a kis- és nagybetűket, ezért az <code>__("Dashboard")</code> hívás a <code>lang/hu/dashboard.php</code> fájlt (tömbként) adta vissza a várt szöveg helyett. Javítás: <code>__("nav.dashboard")</code> — mind a <code>dashboard.blade.php</code>, mind a <code>livewire/layout/navigation.blade.php</code> nézetekben.',
             'en' => '<strong>Dashboard TypeError fix (Windows / HU locale):</strong> The <code>/dashboard</code> page was crashing with <code>TypeError: htmlspecialchars() array given</code>. Root cause: the Windows filesystem is case-insensitive, so <code>__("Dashboard")</code> matched <code>lang/hu/dashboard.php</code> and returned the entire array instead of a string. Fix: <code>__("nav.dashboard")</code> — in both <code>dashboard.blade.php</code> and <code>livewire/layout/navigation.blade.php</code>.', 'de' => '<strong>Dashboard-TypeError-Korrektur (Windows / HU-Locale):</strong> Die Seite <code>/dashboard</code> stürzte mit <code>TypeError: htmlspecialchars() array given</code> ab. Ursache: Das Windows-Dateisystem unterscheidet nicht zwischen Groß- und Kleinschreibung, daher traf <code>__("Dashboard")</code> auf <code>lang/hu/dashboard.php</code> und gab das gesamte Array statt eines Strings zurück. Korrektur: <code>__("nav.dashboard")</code> — in beiden Dateien <code>dashboard.blade.php</code> und <code>livewire/layout/navigation.blade.php</code>.', 'ro' => '<strong>Remediere TypeError Dashboard (Windows / locale HU):</strong> Pagina <code>/dashboard</code> se prăbușea cu <code>TypeError: htmlspecialchars() array given</code>. Cauza principală: sistemul de fișiere Windows nu face distincție între majuscule și minuscule, deci <code>__("Dashboard")</code> se potrivea cu <code>lang/hu/dashboard.php</code> și returna întregul array în loc de un șir. Remediere: <code>__("nav.dashboard")</code> — în ambele fișiere <code>dashboard.blade.php</code> și <code>livewire/layout/navigation.blade.php</code>.', 'sk' => '<strong>Oprava TypeError Dashboardu (Windows / locale HU):</strong> Stránka <code>/dashboard</code> padala s chybou <code>TypeError: htmlspecialchars() array given</code>. Príčina: Súborový systém Windows nerozlišuje veľké a malé písmená, takže <code>__("Dashboard")</code> sa zhodoval s <code>lang/hu/dashboard.php</code> a vrátil celé pole namiesto reťazca. Oprava: <code>__("nav.dashboard")</code> — v oboch súboroch <code>dashboard.blade.php</code> aj <code>livewire/layout/navigation.blade.php</code>.'],
            ['hu' => '<strong>Resend email integráció:</strong> A <code>config/services.php</code>-ben a <code>RESEND_API_KEY</code> env változó neve <code>RESEND_KEY</code>-re javítva a <code>.env</code> fájl tényleges változójának megfelelően. A Resend Laravel csomag mindkét config kulcsot ellenőrzi fallback-ként, így a javítás után az API kulcs helyesen töltődik be.',
             'en' => '<strong>Resend email integration:</strong> In <code>config/services.php</code>, the env variable name was corrected from <code>RESEND_API_KEY</code> to <code>RESEND_KEY</code> to match the actual <code>.env</code> file variable. The Resend Laravel package checks both config keys as fallback, so after the fix the API key loads correctly.', 'de' => '<strong>Resend-E-Mail-Integration:</strong> In <code>config/services.php</code> wurde der Name der Umgebungsvariable von <code>RESEND_API_KEY</code> auf <code>RESEND_KEY</code> korrigiert, um der tatsächlichen <code>.env</code>-Dateivariable zu entsprechen. Das Resend-Laravel-Paket prüft beide Konfigurationsschlüssel als Fallback, sodass der API-Schlüssel nach der Korrektur korrekt geladen wird.', 'ro' => '<strong>Integrare e-mail Resend:</strong> În <code>config/services.php</code>, numele variabilei de mediu a fost corectat din <code>RESEND_API_KEY</code> în <code>RESEND_KEY</code> pentru a corespunde variabilei reale din fișierul <code>.env</code>. Pachetul Resend Laravel verifică ambele chei de configurare ca fallback, astfel după remediere cheia API se încarcă corect.', 'sk' => '<strong>Integrácia e-mailu Resend:</strong> V <code>config/services.php</code> bol názov premennej prostredia opravený z <code>RESEND_API_KEY</code> na <code>RESEND_KEY</code>, aby zodpovedal skutočnej premennej v súbore <code>.env</code>. Balík Resend Laravel kontroluje oba konfiguračné kľúče ako fallback, takže po oprave sa API kľúč načíta správne.'],
        ],
    ],

    [
        'version' => 'v1.10.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 6.', 'en' => 'May 6, 2026', 'de' => '6. Mai 2026', 'ro' => '6 mai 2026', 'sk' => '6. mája 2026'],
        'items' => [
            ['hu' => '<strong>Többnyelvűség (HU/EN) — infrastruktúra:</strong> Bevezetve a <code>SetLocale</code> middleware (session-alapú locale beállítás), <code>LocaleController</code> és a <code>/language/{locale}</code> route. A felső navigációban megjelent a HU / EN nyelvváltó gomb, amely azonnal átkapcsolja az admin felület teljes szövegét.',
             'en' => '<strong>Multi-language support (HU/EN) — infrastructure:</strong> Introduced <code>SetLocale</code> middleware (session-based locale), <code>LocaleController</code> and the <code>/language/{locale}</code> route. A HU / EN language switcher button appeared in the top navigation, instantly switching all admin interface text.', 'de' => '<strong>Mehrsprachige Unterstützung (HU/EN) — Infrastruktur:</strong> <code>SetLocale</code>-Middleware (sitzungsbasierte Locale), <code>LocaleController</code> und die Route <code>/language/{locale}</code> wurden eingeführt. Ein HU/EN-Sprachumschalter erschien in der oberen Navigation und schaltet sofort den gesamten Admin-Schnittstellentext um.', 'ro' => '<strong>Suport multilingv (HU/EN) — infrastructură:</strong> S-a introdus middleware-ul <code>SetLocale</code> (locale bazat pe sesiune), <code>LocaleController</code> și ruta <code>/language/{locale}</code>. Un buton de schimbare a limbii HU/EN a apărut în navigarea superioară, comutând instantaneu tot textul interfeței de administrare.', 'sk' => '<strong>Viacjazyčná podpora (HU/EN) — infraštruktúra:</strong> Bol zavedený middleware <code>SetLocale</code> (locale na základe relácie), <code>LocaleController</code> a routa <code>/language/{locale}</code>. V hornej navigácii sa objavilo tlačidlo prepínača jazykov HU/EN, ktoré okamžite prepína všetok text administrátorského rozhrania.'],
            ['hu' => '<strong>Fordítási fájlok — teljes lefedés:</strong> Létrehozásra és feltöltésre kerültek a <code>lang/hu/</code> és <code>lang/en/</code> PHP nyelvi fájlok minden modulhoz: <code>common</code>, <code>people</code>, <code>events</code>, <code>groups</code>, <code>donations</code>, <code>projects</code>, <code>tasks</code>, <code>users</code>, <code>settings</code>, <code>links</code>, <code>cal</code> (naptár hónap- és napnevek), <code>changelog</code>.',
             'en' => '<strong>Translation files — full coverage:</strong> <code>lang/hu/</code> and <code>lang/en/</code> PHP language files created and populated for every module: <code>common</code>, <code>people</code>, <code>events</code>, <code>groups</code>, <code>donations</code>, <code>projects</code>, <code>tasks</code>, <code>users</code>, <code>settings</code>, <code>links</code>, <code>cal</code> (calendar month and day names), <code>changelog</code>.'],
            ['hu' => '<strong>Admin listaoldalak fordítása:</strong> Minden admin <em>index</em> nézet átírva <code>__()</code> helperekkel — Kapcsolatok, Események, Csoportok, Adományok, Projektek, Feladatok, Felhasználók, Beállítások. A státusz/típus/prioritás badge-ek és a dropdown opciók mostantól a kiválasztott nyelvnek megfelelően jelennek meg.',
             'en' => '<strong>Admin list pages translated:</strong> All admin <em>index</em> views rewritten with <code>__()</code> helpers — Contacts, Events, Groups, Donations, Projects, Tasks, Users, Settings. Status/type/priority badges and dropdown options now display according to the selected language.'],
            ['hu' => '<strong>Admin részletoldalak fordítása:</strong> A Projekt, Esemény, Adomány, Kapcsolat és Csoport részletoldalak (<em>show</em> nézetek) teljes szövege lefordítva. A dinamikus PHP értéktérképek (státusz, prioritás, típus, szerepkör) szintén <code>__()</code> hívásokat használnak.',
             'en' => '<strong>Admin detail pages translated:</strong> Full translation of the Project, Event, Donation, Contact and Group detail (<em>show</em>) views. Dynamic PHP value maps (status, priority, type, role) also use <code>__()</code> calls.'],
            ['hu' => '<strong>Admin űrlapok fordítása:</strong> Minden szerkesztő és létrehozó oldal (<em>form</em> nézetek) átírva — Projektek, Események (teljes oldal + modal partial), Kapcsolatok, Csoportok. A legördülő opciók értéktérképek alapján töltődnek be a megfelelő nyelven.',
             'en' => '<strong>Admin forms translated:</strong> All edit and create pages (<em>form</em> views) rewritten — Projects, Events (full page + modal partial), Contacts, Groups. Dropdown options populate from value maps in the correct language.'],
            ['hu' => '<strong>Naptár és Gantt JS-fordítás:</strong> A Projekt részletoldalon a Naptár és Gantt nézetekhez szükséges hónap/nap neveket PHP <code>__()</code> tömbök tárolják, amelyek <code>@json()</code> direktívával kerülnek a JavaScript kontextusba — így az oldal renderidejében a helyes lokalizált értékek jelennek meg.',
             'en' => '<strong>Calendar and Gantt JS translation:</strong> On the Project detail page, month/day names needed by the Calendar and Gantt views are stored in PHP <code>__()</code> arrays passed into JavaScript context via the <code>@json()</code> directive — rendering correctly localized values at page load time.'],
            ['hu' => '<strong>Nyilvános eseményoldalak fordítása:</strong> A bejelentkezés nélkül elérhető nyilvános regisztrációs oldal (<code>/e/{slug}</code>) és a visszaigazoló oldal is teljes HU/EN fordítást kapott. A <code>&lt;html lang&gt;</code> attribútum mostantól dinamikusan tükrözi az aktuális locale-t.',
             'en' => '<strong>Public event pages translated:</strong> The login-free public registration page (<code>/e/{slug}</code>) and the confirmation page received full HU/EN translation. The <code>&lt;html lang&gt;</code> attribute now dynamically reflects the current locale.'],
            ['hu' => '<strong>Verziókövetés oldal fordítása:</strong> A Changelog oldal data-driven szerkezetre váltott — a verziók bejegyzései PHP tömbökben tárolódnak <code>hu</code>/<code>en</code> kulcsokkal, a sablon locale alapján rendereli a megfelelő szöveget. Badge-ek és dátumok szintén kétnyelvűek.',
             'en' => '<strong>Changelog page translated:</strong> The Changelog page switched to a data-driven structure — version entries are stored in PHP arrays with <code>hu</code>/<code>en</code> keys, the template renders the correct text based on locale. Badges and dates are also bilingual.'],
            ['hu' => '<strong>Súgó szekció teljes kétnyelvűsítése:</strong> Létrehozásra kerültek a <code>lang/hu/help.php</code> és <code>lang/en/help.php</code> fordítási fájlok. Az admin <em>Súgó kezelése</em> oldal és a nyilvános <em>Súgó megtekintő</em> (<code>sugo.blade.php</code>) minden szövege <code>__()</code> helperekkel lett átírva. A <code>&lt;html lang&gt;</code> attribútum dinamikus, az oldal fejléce és gombok is az aktív locale-t tükrözik.',
             'en' => '<strong>Full bilingual support for Help section:</strong> <code>lang/hu/help.php</code> and <code>lang/en/help.php</code> translation files created. All text in the admin <em>Manage Help</em> page and the public <em>Help viewer</em> (<code>sugo.blade.php</code>) rewritten with <code>__()</code> helpers. The <code>&lt;html lang&gt;</code> attribute is now dynamic; the page header and buttons reflect the active locale.'],
            ['hu' => '<strong>Súgó cikkek kétnyelvű adatbázis-sémája:</strong> A <code>help_articles</code> tábla bővítésre került <code>title_en</code> és <code>content_en</code> (nullable) oszlopokkal. Három új súgó cikk jött létre teljes HU+EN tartalommal: <em>Projektek</em>, <em>Verziókövetés</em>, <em>Súgó kezelése</em>. A megjelenítő a locale alapján automatikusan vált a megfelelő nyelvre, hiányzó EN tartalom esetén a magyar verzióra esik vissza.',
             'en' => '<strong>Bilingual database schema for Help articles:</strong> The <code>help_articles</code> table was extended with nullable <code>title_en</code> and <code>content_en</code> columns. Three new help articles were created with full HU+EN content: <em>Projects</em>, <em>Changelog</em>, <em>Manage Help</em>. The viewer automatically switches to the correct language based on locale, falling back to Hungarian if EN content is missing.'],
            ['hu' => '<strong>Súgó admin szerkesztő — kétnyelvű tabos modal:</strong> A Súgó kezelése oldalon az edit modal HU és EN fülekkel bővült, így az adminisztrátor mindkét nyelv tartalmát (cím + szöveg) egymástól függetlenül szerkesztheti és mentheti egyetlen felületen.',
             'en' => '<strong>Help admin editor — bilingual tabbed modal:</strong> The edit modal on the Manage Help page gained HU and EN language tabs, allowing the administrator to edit and save both language versions (title + content) independently from a single interface.'],
            ['hu' => '<strong>Súgó cikkekhez képernyőképek:</strong> Minden súgó cikkhez (<em>Főoldal, Kapcsolatok, Események, Csoportok, Adományok, Felhasználók, Beállítások, Projektek, Verziókövetés, Súgó kezelése</em>) a leírás végére bekerült egy-egy jellemző képernyőkép (<code>/public/img/sugo/</code> mappa). A képek kattintásra teljes képernyős lightbox nézetben nyílnak meg.',
             'en' => '<strong>Screenshots added to Help articles:</strong> A representative screenshot was appended to every help article (<em>Dashboard, Contacts, Events, Groups, Donations, Users, Settings, Projects, Changelog, Manage Help</em>) from the <code>/public/img/sugo/</code> folder. Images open in a full-screen lightbox on click.'],
            ['hu' => '<strong>Súgó megtekintő görgethetőség javítása:</strong> A <code>sugo.blade.php</code> elrendezésében a <code>main</code> elem explicit <code>height: calc(100vh - 60px)</code> és <code>overflow-y: auto</code> stílust kapott, így hosszabb cikkeknél és beillesztett képeknél az oldal megfelelően görgethetővé vált.',
             'en' => '<strong>Help viewer scrolling fix:</strong> In the <code>sugo.blade.php</code> layout the <code>main</code> element received an explicit <code>height: calc(100vh - 60px)</code> and <code>overflow-y: auto</code> style, making the page properly scrollable for longer articles and embedded screenshots.'],
        ],
    ],

    [
        'version' => 'v1.9.0',
        'badge'   => [
            'text'  => ['hu' => 'Fejlesztés', 'en' => 'Improvement', 'de' => 'Verbesserung', 'ro' => 'Îmbunătățire', 'sk' => 'Vylepšenie'],
            'style' => 'background:rgba(64,81,137,0.1);color:#405189;',
        ],
        'date' => ['hu' => '2026. május 6.', 'en' => 'May 6, 2026', 'de' => '6. Mai 2026', 'ro' => '6 mai 2026', 'sk' => '6. mája 2026'],
        'items' => [
            ['hu' => '<strong>Open Core GitHub stratégia — repó szétválasztás:</strong> A projekt nyilvános (<code>nationforge-community</code>) és privát (<code>nationforge-pro</code>) repóra vált szét. A Community MIT licenc alatt elérhető, a Pro fejlesztések külön privát repóban folynak.',
             'en' => '<strong>Open Core GitHub strategy — repo split:</strong> The project was split into a public (<code>nationforge-community</code>) and a private (<code>nationforge-pro</code>) repo. The Community edition is available under MIT license; Pro developments continue in a separate private repo.'],
            ['hu' => '<strong>MIT LICENSE fájl hozzáadása:</strong> A Community kiadáshoz hivatalos <code>LICENSE</code> fájl került (MIT, Programozás Kft. 2026) — enélkül jogilag „minden jog fenntartva" lett volna érvényes.',
             'en' => '<strong>MIT LICENSE file added:</strong> An official <code>LICENSE</code> file (MIT, Programozás Kft. 2026) was added to the Community edition — without it, "all rights reserved" would have applied legally.'],
            ['hu' => '<strong>GitHub README — angol hero kép:</strong> A főoldalon megjelenő marketing kép angol szövegű verzióra cserélve (<em>Stronger communities. More action. Real change.</em>), a GitHub globális fejlesztői közönsége számára.',
             'en' => '<strong>GitHub README — English hero image:</strong> The marketing image on the main page replaced with an English-text version (<em>Stronger communities. More action. Real change.</em>) for GitHub\'s global developer audience.'],
            ['hu' => '<strong>README Pro-szekció linkelése:</strong> Az Open Core táblázatban a Pro oszlop és a call-to-action sor mostantól közvetlenül a <code>nationforge-pro</code> GitHub repóra hivatkozik.',
             'en' => '<strong>README Pro section linked:</strong> In the Open Core table, the Pro column and call-to-action row now link directly to the <code>nationforge-pro</code> GitHub repo.'],
            ['hu' => '<strong>Repó tisztítás — érzékeny fájlok eltávolítása:</strong> A publikus repóból eltávolításra kerültek a helyi fejlesztői eszközök: <code>.claude/</code> config, <code>gitupdate.bat</code>, <code>get_help.php</code>, <code>run_help_fix.php</code>, <code>help_dump.json</code>, <code>help_fix.json</code>. Mindegyik bekerült a <code>.gitignore</code>-ba.',
             'en' => '<strong>Repo cleanup — sensitive files removed:</strong> Local developer tools removed from the public repo: <code>.claude/</code> config, <code>gitupdate.bat</code>, <code>get_help.php</code>, <code>run_help_fix.php</code>, <code>help_dump.json</code>, <code>help_fix.json</code>. All added to <code>.gitignore</code>.'],
            ['hu' => '<strong>Pro repó automatikus Community-szinkron:</strong> A <code>nationforge-pro</code> repóhoz <code>gitupdate.bat</code> szkript készült, amely minden futtatáskor automatikusan behúzza a Community újításait (<code>git fetch community && git merge</code>), majd feltölti a Pro változásokat.',
             'en' => '<strong>Pro repo automatic Community sync:</strong> A <code>gitupdate.bat</code> script was created for the <code>nationforge-pro</code> repo that automatically pulls Community updates (<code>git fetch community && git merge</code>) on every run, then pushes Pro changes.'],
            ['hu' => '<strong>Többnyelvűség a Roadmap-ben:</strong> A tervezett fejlesztések közé bekerült a többnyelvű támogatás (angol / magyar) mint közelgő funkció.',
             'en' => '<strong>Multi-language support in Roadmap:</strong> Multi-language support (English / Hungarian) was added to the planned features as an upcoming item.'],
            ['hu' => '<strong>Nyilvános esemény-regisztráció (új funkció):</strong> Minden <em>published</em> státuszú eseményhez egyedi nyilvános regisztrációs oldal érhető el (<code>/e/{slug}</code>), bejelentkezés nélkül. A látogató megadja nevét, e-mail címét, telefonszámát, kísérők számát és megjegyzését. Kapacitáskorlát esetén vizuális töltöttségsáv jelenik meg, és ha az esemény betelt, a form helyett hibaüzenet látható. Sikeres regisztráció után visszaigazoló oldal fogadja a résztvevőt. Az admin Esemény részletoldalán megjelenik a regisztráltak listája (név, e-mail, telefon, kísérők, időpont), valamint egy „Publikus oldal" gomb.',
             'en' => '<strong>Public event registration (new feature):</strong> Every <em>published</em> event gets a unique public registration page (<code>/e/{slug}</code>), accessible without login. Visitors enter their name, email, phone, number of guests and a note. A visual capacity bar appears when a capacity limit is set; if the event is full, a notice replaces the form. A confirmation page greets the attendee after successful registration. The admin Event detail page displays the registrant list (name, email, phone, guests, time) and a "Public page" button.'],
        ],
    ],

    [
        'version' => 'v1.8.0',
        'date' => ['hu' => '2026. május 5.', 'en' => 'May 5, 2026', 'de' => '5. Mai 2026', 'ro' => '5 mai 2026', 'sk' => '5. mája 2026'],
        'items' => [
            ['hu' => '<strong>Esemény 500-as hiba javítása (EventRsvp model):</strong> Az esemény részletoldal és a szerkesztés utáni átirányítás 500-as szerverhibával végződött, mert a <code>App\Models\EventRsvp</code> osztály hiányzott, noha az <code>event_rsvps</code> tábla az adatbázisban már létezett. A modell létrehozása megszüntette a hibát.',
             'en' => '<strong>Event 500 error fix (EventRsvp model):</strong> The event detail page and the redirect after editing ended with a 500 server error because the <code>App\Models\EventRsvp</code> class was missing, even though the <code>event_rsvps</code> table already existed in the database. Creating the model resolved the error.'],
            ['hu' => '<strong>Esemény létrehozás/módosítás 500-as hiba javítása (ticket_price):</strong> Production MySQL strict módban az üres jegyár mező <code>NULL</code> értékként jutott a <code>NOT NULL</code> oszlopba, ami szerverhibát okozott. A vezérlőben bevezetett <code>?? 0</code> visszavezető érték megoldja a problémát.',
             'en' => '<strong>Event create/update 500 error fix (ticket_price):</strong> In production MySQL strict mode, an empty ticket price field reached the <code>NOT NULL</code> column as <code>NULL</code>, causing a server error. A <code>?? 0</code> fallback introduced in the controller\'s <code>store()</code> and <code>update()</code> methods resolves the issue.'],
            ['hu' => '<strong>Közelgő események helyes számlálása:</strong> A főoldal „Közelgő esemény" számlálója korábban csak a <em>published</em> státuszú eseményeket vette figyelembe, holott az újonnan létrehozott események alapértelmezetten <em>draft</em> státusszal jönnek létre. Mostantól a <em>cancelled</em> és <em>completed</em> kivételével minden jövőbeli esemény beleszámít.',
             'en' => '<strong>Correct counting of upcoming events:</strong> The homepage "Upcoming events" counter previously only counted <em>published</em> events, while newly created events default to <em>draft</em>. Now all future events except <em>cancelled</em> and <em>completed</em> are counted.'],
            ['hu' => '<strong>Főoldal görgetés javítása:</strong> A layout főoszlopa explicit <code>height: calc(100vh - 38px)</code> magasságot kapott, a <code>&lt;main&gt;</code> elem pedig <code>flex:1; min-height:0</code> kombinációval tölti ki a maradék területet.',
             'en' => '<strong>Homepage scroll fix:</strong> The layout\'s main column received an explicit <code>height: calc(100vh - 38px)</code>, and the <code>&lt;main&gt;</code> element fills the remaining area with <code>flex:1; min-height:0</code> — so longer content scrolls correctly.'],
            ['hu' => '<strong>Panel padding egységesítés:</strong> Az Esemény részletoldal Részletek panelén és a főoldal Közelgő események listáján a Tailwind <code>px-5</code> osztályok helyett garantáltan érvényesülő inline <code>padding: 20px</code> stílusok kerültek be.',
             'en' => '<strong>Panel padding standardization:</strong> On the Event detail page\'s Details panel and the homepage Upcoming events list, Tailwind <code>px-5</code> classes were replaced with guaranteed inline <code>padding: 20px</code> styles.'],
            ['hu' => '<strong>Linkgyűjtemény modul (új oldal):</strong> Új <code>/admin/links</code> oldal, amely a mentett hivatkozásokat kategóriánként csoportosítva, kártyás elrendezésben jeleníti meg. Minden kártya tartalmaz színes ikont, leírást és domain-chip feliratot; kattintásra új lapon nyílik meg.',
             'en' => '<strong>Link collection module (new page):</strong> New <code>/admin/links</code> page displaying saved links grouped by category in a card layout. Each card contains a colored icon, description and domain chip label; clicking opens in a new tab.'],
            ['hu' => '<strong>Linkgyűjtemény konfigurálása a Beállításokban:</strong> A Beállítások oldal alján új szekció teszi lehetővé a linkek kezelését (hozzáadás, szerkesztés, törlés) — modal alapú felülettel, cím, URL, kategória, szín, leírás, sorrend és aktív/inaktív mezőkkel.',
             'en' => '<strong>Link collection configuration in Settings:</strong> A new section at the bottom of the Settings page enables link management (add, edit, delete) — with a modal-based interface for title, URL, category, color, description, order and active/inactive fields.'],
            ['hu' => '<strong>Gyorslinkek sáv — valódi URL-ek:</strong> A felső kék sávban lévő gyorslinkek megkapták a tényleges hivatkozásaikat: <em>YouTube</em>, <em>Google Drive</em>, <em>Instagram</em>, <em>Hírek</em>, <em>Infografikonok</em>. Minden link új lapon nyílik meg. A „Linkgyűjtemény" gomb az új <code>/admin/links</code> oldalra navigál.',
             'en' => '<strong>Quick links bar — real URLs:</strong> The quick links in the top blue bar received their actual links: <em>YouTube</em>, <em>Google Drive</em>, <em>Instagram</em>, <em>News</em>, <em>Infographics</em>. All links open in a new tab. The "Link Collection" button navigates to the new <code>/admin/links</code> page.'],
            ['hu' => '<strong>Beállítások oldal teljes szélességű elrendezése:</strong> A korábban középre igazított, korlátozott szélességű Beállítások felület mostantól a teljes rendelkezésre álló területet kitölti. Az Általános és Email szekciók kétoszlopos rácsban helyezkednek el egymás mellett.',
             'en' => '<strong>Settings page full-width layout:</strong> The previously centered, limited-width Settings interface now fills all available space. The General and Email sections are arranged side by side in a two-column grid, with info cards (PHP, Laravel, Environment) below.'],
        ],
    ],

    [
        'version' => 'v1.7.0',
        'date' => ['hu' => '2026. május 3.', 'en' => 'May 3, 2026', 'de' => '3. Mai 2026', 'ro' => '3 mai 2026', 'sk' => '3. mája 2026'],
        'items' => [
            ['hu' => '<strong>Oldalsáv menü egyszerűsítése:</strong> A CRM és Adminisztráció legördülő almenük megszűntek. A Kapcsolatok, Csoportok, Felhasználók, Beállítások, Verziókövetés és Súgó kezelése mostantól közvetlen, önálló menüpontokként érhetők el.',
             'en' => '<strong>Sidebar menu simplification:</strong> The CRM and Administration dropdown submenus were removed. Contacts, Groups, Users, Settings, Changelog and Help are now directly accessible as standalone menu items — reachable in a single click.'],
            ['hu' => '<strong>Csoport részletoldal átrendezése:</strong> Az oldal bal oszlopába kerültek az Adatok és a Tagok panel egymás alatt, míg a Chat ablak a jobb oldali (kétharmados) oszlopot tölti ki — áttekinthetőbb, kétpaneles elrendezés.',
             'en' => '<strong>Group detail page rearrangement:</strong> The Data and Members panels were moved to the left column stacked vertically, while the Chat window fills the right (two-thirds) column — a clearer, two-panel layout.'],
            ['hu' => '<strong>Chat ablak viewport-kitöltés:</strong> A csoport chat ablaka mostantól a böngészőablak teljes magasságát kitölti (topbartól az aljáig), és a jobb szélre van igazítva. JavaScript alapú <code>position: fixed</code> elhelyezés gondoskodik arról, hogy a Livewire poll-frissítés sem állítja vissza a pozíciót.',
             'en' => '<strong>Chat window viewport fill:</strong> The group chat window now fills the full height of the browser window (from topbar to bottom), aligned to the right edge. JavaScript-based <code>position: fixed</code> placement ensures Livewire poll updates don\'t reset the position.'],
            ['hu' => '<strong>Szerepkörök magyar megnevezése:</strong> A Felhasználók létrehozás/szerkesztés modalban és a Csoport részletoldalon a szerepkör nevek angolról magyarra váltottak: <em>super-admin → Főadmin, admin → Admin, editor → Szerkesztő, member → Tag</em>.',
             'en' => '<strong>Localized role names:</strong> In the Users create/edit modal and the Group detail page, role names were updated to match the display locale: <em>super-admin → Főadmin, admin → Admin, editor → Szerkesztő, member → Tag</em>.'],
            ['hu' => '<strong>Dashboard grafikonok (Chart.js):</strong> A főoldalra három látványos grafikon került: <em>Havi adományok</em> oszlopdiagram (utolsó 12 hónap), <em>Kapcsolatok növekedése</em> kettős-tengelyes vonaldiagram, és <em>Kapcsolatok megoszlása</em> fánkdiagram státusz szerint. A grafikonok valós adatbázis-adatokat jelenítenek meg.',
             'en' => '<strong>Dashboard charts (Chart.js):</strong> Three charts added to the homepage: <em>Monthly donations</em> bar chart (last 12 months), <em>Contact growth</em> dual-axis line chart (contacts + donations), and <em>Contact distribution</em> donut chart by status with custom percentage legend. Charts display live database data.'],
        ],
    ],

    [
        'version' => 'v1.6.0',
        'date' => ['hu' => '2026. május 2.', 'en' => 'May 2, 2026', 'de' => '2. Mai 2026', 'ro' => '2 mai 2026', 'sk' => '2. mája 2026'],
        'items' => [
            ['hu' => '<strong>Felhasználók ↔ Csoportok hozzárendelés:</strong> A rendszer felhasználói mostantól csoportokhoz rendelhetők — külön <code>group_user</code> pivot tábla és M:N kapcsolat a <code>User</code> és <code>Group</code> modellek között.',
             'en' => '<strong>Users ↔ Groups assignment:</strong> System users can now be assigned to groups — separate <code>group_user</code> pivot table and M:N relationship between the <code>User</code> and <code>Group</code> models.'],
            ['hu' => '<strong>Csoportok részletoldala — Felhasználók megjelenítése:</strong> A csoport tagok listájában mostantól a Felhasználók is szerepelnek a Kapcsolatok mellett, megjelölve a típusukat (Kapcsolat / Felhasználó), szerepkörük badge-dzsel ellátva.',
             'en' => '<strong>Group detail page — User display:</strong> Users now appear alongside Contacts in the group members list, labeled with their type (Contact / User) and a role badge.'],
            ['hu' => '<strong>Chip/pill csoport-választó:</strong> A Kapcsolatok és Felhasználók szerkesztő modaljaiban a nehézkes többválasztós listát letisztult, kattintható chip-gombok váltják fel — egyetlen kattintással aktiválható/deaktiválható minden csoport.',
             'en' => '<strong>Chip/pill group selector:</strong> In the Contacts and Users edit modals, the cumbersome multi-select list was replaced by clean, clickable chip buttons — each group can be toggled with a single click.'],
            ['hu' => '<strong>Jelszó szem ikon (Felhasználók):</strong> A Felhasználók létrehozás és szerkesztés modalokban a jelszó- és jelszó-megerősítés mezők mellé szem ikon került, amellyel a beírt jelszó láthatóvá tehető.',
             'en' => '<strong>Password eye icon (Users):</strong> An eye icon was added to the password and password confirmation fields in the Users create and edit modals, allowing the entered password to be shown/hidden.'],
            ['hu' => '<strong>Jelszó validációs javítás:</strong> Felhasználó szerkesztésekor az üres jelszó mezők már nem okoznak validációs hibát — a <code>confirmed</code> szabály csak akkor fut le, ha ténylegesen van megadott jelszó.',
             'en' => '<strong>Password validation fix:</strong> When editing a user, empty password fields no longer cause validation errors — the <code>confirmed</code> rule only runs if a password is actually entered.'],
            ['hu' => '<strong>Oldalsáv logo csere:</strong> A bal felső sarokbeli ikon lecserélve a NationForge márkaképnek megfelelő sötétkék hatszög alapú „N" logóra, világoskék szegéllyel.',
             'en' => '<strong>Sidebar logo replacement:</strong> The icon in the top-left corner was replaced with a NationForge-branded dark blue hexagon "N" logo with a light blue border.'],
            ['hu' => '<strong>Oldalsáv menü egyszerűsítése:</strong> A CRM és Adminisztráció legördülő almenük megszűntek — a Kapcsolatok, Csoportok, Felhasználók, Beállítások, Verziókövetés és Súgó mostantól közvetlen menüpontokként érhetők el.',
